const SETTLED_INITIAL_ROWS: usize = 10;
const SETTLED_MORE_ROWS: usize = 25;
const BROWSER_DIVIDER_WIDTH: f32 = 1.0;
/// How often working dots, pulses, and running timers advance. They move a
/// few times a second instead of on every frame: a repeating animation asks
/// for a frame at display rate, and each frame re-renders the whole window.
const PULSE_INTERVAL: Duration = Duration::from_millis(400);

/// Steps of the shared pulse, advanced only while something is working.
static PULSE_FRAME: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

thread_local! {
    /// Whether the last frame drew anything that moves with the pulse: a
    /// working dot, or a running timer. When nothing did, the pulse has no
    /// reason to redraw the window.
    static ANIMATION_DRAWN: Cell<bool> = const { Cell::new(false) };
}

/// Notes that this frame draws something the pulse moves.
fn mark_animated() {
    ANIMATION_DRAWN.with(|drawn| drawn.set(true));
}

fn pulse_frame() -> usize {
    mark_animated();
    pulse_step()
}

/// The pulse's step, for the layer that draws what moves with it: reading it
/// there asks nothing of the window.
fn pulse_step() -> usize {
    PULSE_FRAME.load(std::sync::atomic::Ordering::Relaxed)
}

thread_local! {
    /// Settings › Appearance › Reduce motion, for the drawing helpers that
    /// have no settings at hand. Set when settings load and when the toggle
    /// changes. Everything draws on one thread.
    static REDUCE_MOTION: Cell<bool> = const { Cell::new(false) };
}

fn reduce_motion() -> bool {
    REDUCE_MOTION.with(Cell::get)
}

fn set_reduce_motion(reduce: bool) {
    REDUCE_MOTION.with(|motion| motion.set(reduce));
}

/// Opacity of a pulsing dot on the current pulse step. With motion reduced
/// the dot holds steady, and asks for no redraw.
fn pulse_opacity() -> f32 {
    if reduce_motion() {
        return 1.0;
    }
    pulse_opacity_at(pulse_frame(), frame_colors())
}

/// The pulse's four steps, from the theme's floor, where the working ink
/// still reads at 3:1 on every ground, to full strength and back.
fn pulse_opacity_at(step: usize, colors: ThemeColors) -> f32 {
    let floor = f32::from(colors.pulse_floor) / 255.0;
    let middle = (floor + 1.0) / 2.0;
    [floor, middle, 1.0, middle][step % 4]
}

/// What moves with the shared pulse or the terminal's blink: a working dot,
/// three working dots, the terminal's cursor. Where the window has a
/// [`PulseLayer`], the window's view lays out an empty place for each and
/// notes it here as it paints, and the layer draws it there, over the
/// window. A pulse step or a blink then redraws the layer alone, not the
/// sidebar, the header and the composer around the marks.
#[derive(Default)]
struct Animated {
    marks: Vec<AnimatedMark>,
    /// Where something floats over the page, such as the error banner: no
    /// mark is drawn through it.
    occluders: Vec<Bounds<Pixels>>,
    /// Whether the terminal's cursor is in the lit half of its blink.
    cursor_on: bool,
}

struct AnimatedMark {
    bounds: Bounds<Pixels>,
    /// The clip of the scroll area the mark is in.
    mask: gpui::ContentMask<Pixels>,
    kind: AnimatedKind,
}

enum AnimatedKind {
    /// A dot that pulses, in `color`.
    Dot { color: u32 },
    /// Three dots that fill in one by one, set as text.
    Dots { color: u32, text: TextLook },
    /// Text that keeps up with the time, such as a running agent's timer:
    /// what it says at each moment, in `color`, and how many letters the
    /// window laid it out with.
    Clock {
        text: ClockText,
        color: u32,
        look: TextLook,
        laid: usize,
    },
    /// The terminal's cursor on the cell holding `glyph`: the cell in
    /// `fill`, the glyph in `ink`.
    Cursor {
        glyph: SharedString,
        fill: u32,
        ink: u32,
        text: TextLook,
    },
}

/// The font a mark set as text is shaped in, as the place it is in sets it.
#[derive(Clone)]
struct TextLook {
    font: gpui::Font,
    size: Pixels,
    line_height: Pixels,
}

impl TextLook {
    fn here(window: &Window) -> Self {
        let style = window.text_style();
        Self {
            font: style.font(),
            size: style.font_size.to_pixels(window.rem_size()),
            line_height: window.line_height(),
        }
    }

    fn paint(
        &self,
        text: SharedString,
        inks: &[gpui::Hsla],
        origin: Point<Pixels>,
        window: &mut Window,
        cx: &mut App,
    ) {
        let runs = inks
            .iter()
            .zip(text.char_indices().map(|(_, c)| c.len_utf8()))
            .map(|(ink, len)| TextRun {
                len,
                font: self.font.clone(),
                color: *ink,
                background_color: None,
                underline: None,
                strikethrough: None,
            })
            .collect::<Vec<_>>();
        let line = window
            .text_system()
            .shape_line(text, self.size, &runs, None);
        let _ = line.paint(origin, self.line_height, window, cx);
    }
}

/// What a [`AnimatedKind::Clock`] says at a moment, in milliseconds since
/// the epoch.
type ClockText = Rc<dyn Fn(u64) -> String>;

/// Now, in milliseconds since the epoch.
fn epoch_millis() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|elapsed| elapsed.as_millis() as u64)
        .unwrap_or(0)
}

thread_local! {
    /// Whether this frame's text that keeps up with the time goes to the
    /// [`PulseLayer`]: the window has one and nothing covers the page. A
    /// timer is no motion, so it does with motion reduced too.
    static CLOCKS_LAYERED: Cell<bool> = const { Cell::new(false) };
}

/// Text that keeps up with the time, such as a running agent's timer, in
/// `color`: drawn by the [`PulseLayer`] where the window has one, which
/// alone redraws as the pulse steps, over a place the text takes as it
/// reads now; else in place, which redraws the window with the pulse.
fn live_text(text: impl Fn(u64) -> String + 'static, color: u32) -> gpui::Div {
    let text: ClockText = Rc::new(text);
    let now = text(epoch_millis());
    if !CLOCKS_LAYERED.with(Cell::get) {
        mark_animated();
        return div().text_color(rgb(color)).child(now);
    }
    let laid = now.chars().count();
    div()
        .text_color(gpui::transparent_black())
        .child(now)
        .child(animated_place(move |window| AnimatedKind::Clock {
            text: text.clone(),
            color,
            look: TextLook::here(window),
            laid,
        }))
}

/// Whether a timer the layer draws no longer fits the room the window laid
/// out for it, so the window must lay it out again.
fn clocks_outgrew_their_room() -> bool {
    let now = epoch_millis();
    ANIMATED.with(|animated| {
        animated.borrow().marks.iter().any(|mark| match &mark.kind {
            AnimatedKind::Clock { text, laid, .. } => text(now).chars().count() != *laid,
            _ => false,
        })
    })
}

thread_local! {
    static ANIMATED: RefCell<Animated> = RefCell::default();
    /// Whether this frame's marks go to the [`PulseLayer`]: the window has
    /// one, nothing covers the page, and motion is not reduced.
    static LAYERED: Cell<bool> = const { Cell::new(false) };
}

fn layered() -> bool {
    LAYERED.with(Cell::get)
}

/// Notes a mark where it is painted: an element that takes no room, laid
/// over the place the mark has.
fn animated_place(kind: impl Fn(&Window) -> AnimatedKind + 'static) -> impl IntoElement {
    canvas(
        move |bounds, window, _| {
            let mark = AnimatedMark {
                bounds,
                mask: window.content_mask(),
                kind: kind(window),
            };
            ANIMATED.with(|animated| animated.borrow_mut().marks.push(mark));
        },
        |_, _, _, _| {},
    )
    .absolute()
    .inset_0()
}

/// Notes where something floats over the page, which marks under it leave
/// alone.
fn animated_occluder() -> impl IntoElement {
    canvas(
        |bounds, _, _| ANIMATED.with(|animated| animated.borrow_mut().occluders.push(bounds)),
        |_, _, _, _| {},
    )
    .absolute()
    .inset_0()
}

/// A round dot of `size` in `color` that pulses while `pulsing`: drawn by
/// the [`PulseLayer`] where there is one, else in place.
fn pulse_dot(size: f32, color: u32, pulsing: bool) -> gpui::Div {
    let dot = div().size(px(size)).flex_none().rounded_full();
    if !pulsing {
        return dot.bg(rgb(color));
    }
    if layered() {
        return dot.child(animated_place(move |_| AnimatedKind::Dot { color }));
    }
    dot.bg(rgb(color)).opacity(pulse_opacity())
}

/// Draws what moves with the pulse and the blink, over the window, at the
/// places the window's view noted. It takes no input: every click goes to
/// the view under it.
struct PulseLayer;

impl Render for PulseLayer {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        canvas(
            |_, _, _| {},
            |_, _, window, cx| {
                let step = pulse_step();
                ANIMATED.with(|animated| {
                    let animated = animated.borrow();
                    for mark in &animated.marks {
                        if animated
                            .occluders
                            .iter()
                            .any(|over| over.intersects(&mark.bounds))
                        {
                            continue;
                        }
                        window.with_content_mask(Some(mark.mask.clone()), |window| {
                            paint_animated(mark, step, animated.cursor_on, window, cx);
                        });
                    }
                });
            },
        )
        .absolute()
        .inset_0()
    }
}

fn paint_animated(
    mark: &AnimatedMark,
    step: usize,
    cursor_on: bool,
    window: &mut Window,
    cx: &mut App,
) {
    let alpha = |color: u32, alpha: f32| -> gpui::Hsla {
        rgba((color << 8) | (alpha * 255.0).round() as u32).into()
    };
    match &mark.kind {
        AnimatedKind::Dot { color } => {
            let radius = mark.bounds.size.width.min(mark.bounds.size.height) / 2.0;
            window.paint_quad(
                gpui::fill(
                    mark.bounds,
                    alpha(*color, pulse_opacity_at(step, frame_colors())),
                )
                .corner_radii(radius),
            );
        }
        AnimatedKind::Dots { color, text } => {
            let inks = working_dot_alphas(step).map(|lit| alpha(*color, f32::from(lit) / 255.0));
            text.paint("...".into(), &inks, mark.bounds.origin, window, cx);
        }
        AnimatedKind::Clock {
            text, color, look, ..
        } => {
            let now = text(epoch_millis());
            let inks = vec![rgb(*color).into(); now.chars().count()];
            look.paint(now.into(), &inks, mark.bounds.origin, window, cx);
        }
        AnimatedKind::Cursor {
            glyph,
            fill,
            ink,
            text,
        } => {
            if !cursor_on {
                return;
            }
            window.paint_quad(gpui::fill(mark.bounds, rgb(*fill)));
            let inks = vec![rgb(*ink).into(); glyph.chars().count()];
            text.paint(glyph.clone(), &inks, mark.bounds.origin, window, cx);
        }
    }
}

/// The window's root: the workspace, drawn once for each change to it, and
/// over it the [`PulseLayer`], which alone redraws as the pulse steps and
/// the terminal's cursor blinks.
struct XdWindow {
    desktop: Entity<XdDesktop>,
    layer: Entity<PulseLayer>,
}

impl XdWindow {
    fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
        let layer = cx.new(|_| PulseLayer);
        let desktop = cx.new(|cx| XdDesktop::new(window, cx));
        desktop.update(cx, |desktop, _| desktop.pulse_layer = Some(layer.clone()));
        Self { desktop, layer }
    }
}

impl Render for XdWindow {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        div()
            .size_full()
            .relative()
            // Kept from frame to frame while nothing in it changed, so a
            // frame for the layer alone reuses all of it.
            .child(
                gpui::AnyView::from(self.desktop.clone())
                    .cached(gpui::StyleRefinement::default().size_full()),
            )
            .child(self.layer.clone())
    }
}

/// Narrowest the browser pane can be dragged.
const BROWSER_MIN_WIDTH: f32 = 280.0;
/// Width the browser always leaves for the session beside it. Past the point
/// where the catalog no longer fits, the catalog compacts instead.
const BROWSER_SESSION_MIN_WIDTH: f32 = 460.0;

/// The narrowest the browser goes when the window cannot hold it at its
/// minimum beside the session: it gives up its room before the session does,
/// down to this, where its toolbar still fits.
const BROWSER_SQUEEZED_WIDTH: f32 = 200.0;

/// The browser can take any share of the window that still leaves the session
/// its minimum, so it is not held at a fixed width on wide screens. In a
/// window too narrow for both minimums the browser yields first.
fn browser_pane_width(requested: u16, window_width: f32) -> f32 {
    let room = window_width - BROWSER_DIVIDER_WIDTH - BROWSER_SESSION_MIN_WIDTH;
    let least = BROWSER_MIN_WIDTH.min(room.max(BROWSER_SQUEEZED_WIDTH));
    f32::from(requested).clamp(least, room.max(least))
}

/// `room` is the window width left of the browser. The catalog hides once that
/// drops below 640, so the session keeps its minimum wherever the catalog shows.
fn catalog_pane_width(requested: u16, room: f32) -> f32 {
    f32::from(requested).clamp(
        CATALOG_MIN_WIDTH,
        (room - CATALOG_SESSION_MIN_WIDTH).clamp(CATALOG_MIN_WIDTH, CATALOG_MAX_WIDTH),
    )
}

/// The height of a secret question's masked field: a line of the message
/// box's type and its frame.
const SECRET_FIELD_HEIGHT: f32 = 40.0;

/// One of the window's dividers, which a drag or the keyboard moves.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Divider {
    /// Between the sidebar and the session.
    Sidebar,
    /// Between the session and the side pane.
    SidePane,
    /// Above the terminal under the chat.
    Terminal,
}

impl Divider {
    /// Its Tab stop's id.
    const fn stop(self) -> &'static str {
        match self {
            Self::Sidebar => "divider:sidebar",
            Self::SidePane => "divider:side-pane",
            Self::Terminal => "divider:terminal",
        }
    }

    /// What the name under its ring says.
    const fn name(self) -> &'static str {
        match self {
            Self::Sidebar => "Sidebar's edge: Left / Right moves it, Home / End to either end",
            Self::SidePane => "Side pane's edge: Left / Right moves it, Home / End to either end",
            Self::Terminal => "Terminal's edge: Up / Down moves it, Home / End to either end",
        }
    }

    fn from_stop(id: &str) -> Option<Self> {
        [Self::Sidebar, Self::SidePane, Self::Terminal]
            .into_iter()
            .find(|divider| divider.stop() == id)
    }

    /// How far a key moves the pane it bounds: Left and Right for the two
    /// upright dividers, Up and Down for the terminal's, each the way it
    /// points, and Home and End all the way to the left or top and to the
    /// right or bottom. `None` for a key across the divider.
    fn grow_for(self, key: ArrowKey) -> Option<f32> {
        const ALL_THE_WAY: f32 = 100_000.0;
        let (toward_start, toward_end) = match (self, key) {
            (Self::Sidebar | Self::SidePane, ArrowKey::Left) | (Self::Terminal, ArrowKey::Up) => {
                (PANE_KEY_STEP, 0.0)
            }
            (Self::Sidebar | Self::SidePane, ArrowKey::Right)
            | (Self::Terminal, ArrowKey::Down) => (0.0, PANE_KEY_STEP),
            (_, ArrowKey::Home) => (ALL_THE_WAY, 0.0),
            (_, ArrowKey::End) => (0.0, ALL_THE_WAY),
            _ => return None,
        };
        // The sidebar grows as its edge moves right; the side pane and the
        // terminal grow as theirs moves left or up.
        Some(match self {
            Self::Sidebar => toward_end - toward_start,
            Self::SidePane | Self::Terminal => toward_start - toward_end,
        })
    }
}

/// An arrow key, Home or End, as the control the ring is on reads it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ArrowKey {
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
}

/// How far one press of a divider's keys moves it.
const PANE_KEY_STEP: f32 = 16.0;

/// What the window keeps above and below the terminal under the chat: the
/// title bar, the session's header and the panel's own tab row.
const TERMINAL_PANEL_CHROME: f32 = 86.0;

/// Keep room for the chat when sizing the bottom terminal.
fn bottom_terminal_height(requested: u16, available: f32) -> f32 {
    f32::from(requested).clamp(120.0, (available - 180.0).clamp(120.0, 600.0))
}

fn working_dot_alphas(frame: usize) -> [u8; 3] {
    let lit = frame % 4;
    std::array::from_fn(|index| if index < lit { 0xff } else { 0x4d })
}

/// Three dots that fill in one by one, in step with the shared pulse. The
/// size is inherited so the dots sit on the label's baseline.
fn working_dots(_instance: usize, color: u32) -> gpui::AnyElement {
    if layered() {
        // The place the dots take, and the font they are set in.
        return div()
            .relative()
            .w(px(13.0))
            .flex_none()
            .child(div().invisible().child("..."))
            .child(animated_place(move |window| AnimatedKind::Dots {
                color,
                text: TextLook::here(window),
            }))
            .into_any_element();
    }
    // With motion reduced all three dots stay lit.
    let frame = if reduce_motion() { 3 } else { pulse_frame() };
    let highlights = working_dot_alphas(frame)
        .into_iter()
        .enumerate()
        .map(|(index, alpha)| {
            (
                index..index + 1,
                HighlightStyle {
                    color: Some(rgba((color << 8) | u32::from(alpha)).into()),
                    ..Default::default()
                },
            )
        });
    div()
        .w(px(13.0))
        .flex_none()
        .child(StyledText::new("...").with_highlights(highlights))
        .into_any_element()
}

fn plus_icon(color: u32) -> gpui::AnyElement {
    div()
        .relative()
        .size(px(16.0))
        .child(
            div()
                .absolute()
                .left(px(3.0))
                .top(px(7.0))
                .w(px(10.0))
                .h(px(2.0))
                .rounded_full()
                .bg(rgb(color)),
        )
        .child(
            div()
                .absolute()
                .left(px(7.0))
                .top(px(3.0))
                .w(px(2.0))
                .h(px(10.0))
                .rounded_full()
                .bg(rgb(color)),
        )
        .into_any_element()
}

fn xd_mark(color: u32) -> gpui::AnyElement {
    svg()
        .path(XD_MARK_ICON)
        .size(px(20.0))
        .flex_none()
        .text_color(rgb(color))
        .into_any_element()
}

fn settings_switch(colors: ThemeColors, enabled: bool) -> gpui::AnyElement {
    // Off, its track is a ground of its own, so the control edge shows where
    // it is; on, the edge is the accent fill's. The knob sits inside it.
    div()
        .w(px(38.0))
        .h(px(22.0))
        .flex_none()
        .rounded_full()
        .border_1()
        .border_color(rgb(if enabled {
            colors.accent
        } else {
            colors.control_border
        }))
        .bg(rgb(if enabled {
            colors.accent
        } else {
            colors.surface_high
        }))
        .child(
            div()
                .mt(px(3.0 - SWITCH_EDGE))
                .ml(px(if enabled { 19.0 } else { 3.0 } - SWITCH_EDGE))
                .size(px(16.0))
                .rounded_full()
                .bg(rgb(if enabled {
                    colors.accent_text
                } else {
                    colors.muted
                })),
        )
        .into_any_element()
}

/// The width of a switch's edge, which its knob sits inside.
const SWITCH_EDGE: f32 = 1.0;

/// What a session row shows of the sessions its agent started, which list
/// right below it.
struct SessionFold {
    /// The session's key, which the folded set holds.
    key: String,
    /// How many sessions below it its agent started, or theirs did.
    workers: usize,
    folded: bool,
    /// The signals of the sessions folding hides, so the row still shows
    /// which of them need a look.
    hidden: Vec<SessionSignal>,
}

/// How many sessions of each kind the landing page lists before it says
/// only how many more there are.
const HOME_ROWS: usize = 6;

/// A session the landing page lists because it waits on the user or works.
#[derive(Clone, Debug, PartialEq, Eq)]
struct HomeSession {
    project_id: String,
    project: String,
    chat_id: String,
    agent: AgentCli,
    title: String,
    signal: SessionSignal,
}

/// What the landing page shows once a chat is left.
#[derive(Clone, Debug, PartialEq, Eq)]
enum HomeOverview {
    /// No project yet: the welcome.
    FirstRun,
    Projects {
        /// Sessions waiting on the user, in the sidebar's order.
        waiting: Vec<HomeSession>,
        /// Sessions at work, or waiting on their own agents and shells.
        working: Vec<HomeSession>,
        /// Every session listed in the sidebar.
        sessions: usize,
        /// Sessions with a finished turn the user has not seen, and paused ones:
        /// neither waits nor works, but neither is idle.
        finished: usize,
        paused: usize,
        /// The last session, unless it is already listed above.
        resume: Option<(String, String, AgentCli, String)>,
        /// The project a new session starts in, and its name.
        new_session: Option<(String, String)>,
    },
}

/// The landing page's heading: what waits on the user first, then what works.
fn home_heading(waiting: usize, working: usize, sessions: usize) -> String {
    match (waiting, working) {
        (1, _) => "1 session is waiting on you".into(),
        (2.., _) => format!("{waiting} sessions are waiting on you"),
        (0, 1) => "1 session is working".into(),
        (0, 2..) => format!("{working} sessions are working"),
        (0, 0) if sessions == 0 => "No sessions yet".into(),
        (0, 0) => "Nothing is waiting on you".into(),
    }
}

/// The line under a quiet landing page's heading: what the sessions that
/// neither wait nor work are doing, or that they are all idle.
fn home_quiet_lead(finished: usize, paused: usize) -> String {
    let sessions = |count: usize| {
        if count == 1 {
            "1 session".to_owned()
        } else {
            format!("{count} sessions")
        }
    };
    match (finished, paused) {
        (0, 0) => "All sessions are idle.".to_owned(),
        (finished, 0) => format!("{} finished since you looked.", sessions(finished)),
        (0, 1) => "1 session is paused.".to_owned(),
        (0, paused) => format!("{paused} sessions are paused."),
        (finished, 1) => format!(
            "{} finished since you looked, and 1 is paused.",
            sessions(finished)
        ),
        (finished, paused) => format!(
            "{} finished since you looked, and {paused} are paused.",
            sessions(finished)
        ),
    }
}

/// What a session's signal tab says about its agent.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SessionSignal {
    Idle,
    Working,
    /// An approval or question is waiting on the user. The only amber state.
    Waiting,
    /// No turn is running, but the agent's background agents and shells are:
    /// it is waiting on that many of them.
    Background(u32),
    /// A finished turn the user has not opened yet.
    Done,
    /// Pausing every chat stopped it, and it waits to resume.
    Paused,
}

impl SessionSignal {
    /// `background` counts the tasks the session is waiting on, which only
    /// matters while no turn runs.
    fn of(working: bool, waiting: bool, unread: bool, background: u32) -> Self {
        if waiting {
            Self::Waiting
        } else if working {
            Self::Working
        } else if background > 0 {
            Self::Background(background)
        } else if unread {
            Self::Done
        } else {
            Self::Idle
        }
    }

    /// A paused session says so until something else needs saying: it is
    /// stopped, so nothing runs, and a pause outranks a finished turn.
    fn or_paused(self, paused: bool) -> Self {
        match self {
            Self::Idle | Self::Done if paused => Self::Paused,
            signal => signal,
        }
    }

    fn color(self, colors: ThemeColors) -> u32 {
        match self {
            Self::Idle => colors.faint,
            Self::Paused | Self::Background(_) => colors.muted,
            Self::Working => colors.working,
            Self::Waiting => colors.waiting,
            Self::Done => colors.done,
        }
    }

    fn label(self) -> SharedString {
        match self {
            Self::Idle => "Idle".into(),
            Self::Working => "Working".into(),
            Self::Waiting => "Waiting on you".into(),
            Self::Background(count) => background_label(count).into(),
            Self::Done => "Done".into(),
            Self::Paused => "Paused".into(),
        }
    }
}

/// What a chat waiting on its background tasks says, such as "Waiting on 2
/// background tasks".
fn background_label(count: u32) -> String {
    format!(
        "Waiting on {count} background task{}",
        if count == 1 { "" } else { "s" }
    )
}

/// How many background tasks the row below the chat names: between turns,
/// the background agents and shells still running, unless the agents tray
/// already lists at least that many running in the transcript, so the row
/// would only repeat it. Tasks the transcript does not show, such as hidden
/// ones or those in pages not loaded yet, still bring the row back.
fn background_row_count(working: bool, listed: usize, waiting_on: u32) -> u32 {
    if working || listed >= waiting_on as usize {
        0
    } else {
        waiting_on
    }
}

/// The mark for work still running in the background: a gray ring that holds
/// still, where a working dot is green, filled, and pulses.
fn background_ring(size: f32, color: u32) -> gpui::Div {
    div()
        .size(px(size))
        .flex_none()
        .rounded_full()
        .border(px(1.5))
        .border_color(rgb(color))
}

/// The ring that says a session waits on the user. Reserved for that state.
fn waiting_ring(colors: ThemeColors) -> gpui::Div {
    div()
        .size(px(9.0))
        .flex_none()
        .rounded_full()
        .border(px(1.5))
        .border_color(rgb(colors.waiting))
}

/// The shape that says what a session is doing, shared with Android so
/// status never rests on colour alone: a filled dot that pulses for work, a
/// hollow ring for waiting on the user, a check for a finished turn not yet
/// read, two bars for paused, and a gray ring for background tasks. `size` is
/// the dot's; the other marks are drawn to weigh the same beside it.
fn status_mark(signal: SessionSignal, size: f32, colors: ThemeColors) -> Option<gpui::AnyElement> {
    let color = signal.color(colors);
    Some(match signal {
        SessionSignal::Idle => return None,
        SessionSignal::Working => pulse_dot(size, color, true).into_any_element(),
        SessionSignal::Waiting => waiting_ring(colors).size(px(size + 2.0)).into_any_element(),
        SessionSignal::Background(_) => background_ring(size + 1.0, color).into_any_element(),
        // The drawn check and bars fill about half of their box.
        SessionSignal::Done => icon(CHECK_ICON, size + 5.0, color),
        SessionSignal::Paused => icon(PAUSE_ICON, size + 2.0, color),
    })
}

/// What a bare count in the sidebar counts, such as "3 sessions".
fn counted(count: usize, one: &str, many: &str) -> String {
    format!("{count} {}", if count == 1 { one } else { many })
}

/// A status mark, or a bare count, that names itself under the pointer.
fn labelled_mark(
    id: impl Into<gpui::ElementId>,
    label: impl Into<SharedString>,
    colors: ThemeColors,
    mark: impl IntoElement,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .flex_none()
        .flex()
        .items_center()
        .when(!under_a_dialog(), |mark| {
            mark.tooltip(pane_tooltip(label, colors))
        })
        .child(mark)
}

/// The small status mark at the end of a session row, and nothing for a quiet
/// session so a list of them reads quiet. Waiting on the user is the one state
/// that also says so in words; the others say it under the pointer.
fn signal_tab(signal: SessionSignal, colors: ThemeColors) -> Option<gpui::AnyElement> {
    let color = signal.color(colors);
    let mark = status_mark(signal, 7.0, colors)?;
    Some(match signal {
        SessionSignal::Waiting => div()
            .flex_none()
            .flex()
            .items_center()
            .gap(px(6.0))
            .text_size(text_px(TEXT_CAPTION))
            .text_color(rgb(color))
            .child(mark)
            .child("Waiting on you")
            .into_any_element(),
        SessionSignal::Background(count) => labelled_mark(
            "session-signal",
            signal.label(),
            colors,
            div()
                .flex()
                .items_center()
                .gap(px(4.0))
                .text_size(text_px(TEXT_CAPTION))
                .text_color(rgb(color))
                .child(count.to_string())
                .child(mark),
        )
        .into_any_element(),
        _ => labelled_mark("session-signal", signal.label(), colors, mark).into_any_element(),
    })
}

/// The word and dot color for the row under a running turn. A turn held up on
/// an approval or question is not doing anything, so it stops reading as work.
fn turn_status(waiting: bool, colors: ThemeColors) -> (&'static str, u32) {
    if waiting {
        ("Waiting on you", colors.waiting)
    } else {
        ("Working", colors.working)
    }
}

thread_local! {
    /// The theme the frame is drawn in, for a tooltip built where no colours
    /// are at hand.
    static FRAME_COLORS: Cell<Option<ThemeColors>> = const { Cell::new(None) };
    /// The window's width and height as the frame is drawn, for a helper
    /// that sizes something to the window with no window at hand.
    static FRAME_VIEWPORT: Cell<(f32, f32)> = const { Cell::new((1180.0, 780.0)) };
    /// The labels the last frames had to cut short, by their text and the
    /// place in the code that draws them, so the next frame gives each a
    /// tooltip that reads it out in full.
    static CUT_LABELS: RefCell<HashSet<u64>> = RefCell::default();
    /// Where each label the last frame cut short was painted, and its whole
    /// text: the control the keyboard is on reads its label out from these.
    static CUT_PAINTED: RefCell<Vec<(Bounds<Pixels>, SharedString)>> = RefCell::default();
    /// A menu or dialog is open over the window. What lies under it keeps
    /// its tooltips to itself: one that came up after a right-click would
    /// sit on top of the menu the click opened.
    static UNDER_A_DIALOG: Cell<bool> = const { Cell::new(false) };
}

/// Whether the window the frame is drawn in is short: see [`SHORT_WINDOW`].
fn short_window() -> bool {
    FRAME_VIEWPORT.with(Cell::get).1 < SHORT_WINDOW
}

fn under_a_dialog() -> bool {
    UNDER_A_DIALOG.with(Cell::get)
}

fn frame_colors() -> ThemeColors {
    FRAME_COLORS
        .with(Cell::get)
        .unwrap_or(ThemePreset::Dark.colors())
}

/// One line of text as wide as it needs, down to whatever room its row leaves,
/// ending in an ellipsis when that is too little. Size it from the outside.
/// While it is cut short, the pointer over it shows the whole of it.
///
/// GPUI's own `.truncate()` is not used. It cuts the text to the first width
/// it is measured at and keeps that result, and layout may measure a label
/// at more than one width: first with none, in a flexible row, or at a width
/// an outer box gives up later. The whole text got shaped, then clipped
/// mid-letter. So the label lays out as an unseen copy of its text, which
/// gives it its natural width and its line's height, and the text is drawn
/// over that once the label has its place, cut to the room it really has.
#[track_caller]
fn truncating_label(text: impl Into<SharedString>) -> gpui::Stateful<gpui::Div> {
    let text: SharedString = text.into();
    // One line: GPUI shapes no line break, so a title that has one, such as
    // a chat named from a pasted message, reads on with a space instead.
    let text: SharedString = if text.contains(['\n', '\r']) {
        text.split(['\n', '\r'])
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>()
            .join(" ")
            .into()
    } else {
        text
    };
    let site = std::panic::Location::caller();
    let mut hasher = DefaultHasher::new();
    (text.as_ref(), site.file(), site.line(), site.column()).hash(&mut hasher);
    let key = hasher.finish();
    let cut = CUT_LABELS.with(|cut| cut.borrow().contains(&key)) && !under_a_dialog();
    let drawn = text.clone();
    div()
        .relative()
        .min_w_0()
        .overflow_hidden()
        .child(div().invisible().whitespace_nowrap().child(text.clone()))
        .child(
            canvas(
                move |bounds, window, _| {
                    let style = window.text_style();
                    let size = style.font_size.to_pixels(window.rem_size());
                    let shape = |text: SharedString| {
                        let run = style.to_run(text.len());
                        window.text_system().shape_line(text, size, &[run], None)
                    };
                    let room = bounds.size.width + gpui::px(0.5);
                    let whole = shape(drawn.clone());
                    let over = whole.width > room;
                    if over {
                        CUT_PAINTED.with(|cut| cut.borrow_mut().push((bounds, drawn.clone())));
                    }
                    CUT_LABELS.with(|cut| {
                        let mut cut = cut.borrow_mut();
                        if !over {
                            cut.remove(&key);
                        } else {
                            // Labels no longer drawn are never measured again.
                            if cut.len() > 4096 {
                                cut.clear();
                            }
                            cut.insert(key);
                        }
                    });
                    let line = if over {
                        let short =
                            cut_to_fit(&drawn, |text| shape(text.to_owned().into()).width <= room);
                        shape(short.into())
                    } else {
                        whole
                    };
                    if cfg!(test) {
                        DRAWN_LABELS.with(|labels| labels.borrow_mut().push(line.text.to_string()));
                    }
                    (line, window.line_height())
                },
                |bounds, (line, line_height), window, cx| {
                    let _ = line.paint(bounds.origin, line_height, window, cx);
                },
            )
            // Over the unseen copy, not after it.
            .absolute()
            .inset_0(),
        )
        .id(gpui::ElementId::NamedInteger("label".into(), key))
        .when(cut, |label| {
            label.tooltip(pane_tooltip(text, frame_colors()))
        })
}

thread_local! {
    /// What each [`truncating_label`] of the last frames drew, in order.
    /// Kept only while the tests run, which read it back.
    static DRAWN_LABELS: RefCell<Vec<String>> = RefCell::default();
}

/// The most of `text` that `fits` with an ellipsis after it, and the
/// ellipsis. Spaces before the ellipsis are dropped. Where nothing fits it
/// is the ellipsis alone.
fn cut_to_fit(text: &str, mut fits: impl FnMut(&str) -> bool) -> String {
    let ends = text
        .char_indices()
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    let cut = |kept: usize| format!("{}…", text[..ends[kept]].trim_end());
    // `ends[kept]` is where the text ends with `kept` characters kept. More
    // text never fits where less did not, so the most that fits is found by
    // halving.
    let (mut fitting, mut over) = (0, ends.len());
    while fitting + 1 < over {
        let middle = (fitting + over) / 2;
        if fits(&cut(middle)) {
            fitting = middle;
        } else {
            over = middle;
        }
    }
    if ends.is_empty() {
        "…".into()
    } else {
        cut(fitting)
    }
}

/// How wide `text` is on one line, in the face and size given.
fn line_width(
    text: &str,
    family: &'static str,
    weight: FontWeight,
    size: f32,
    window: &Window,
) -> f32 {
    if text.is_empty() {
        return 0.0;
    }
    let run = TextRun {
        len: text.len(),
        font: gpui::Font {
            weight,
            ..gpui::font(family)
        },
        color: gpui::black(),
        background_color: None,
        underline: None,
        strikethrough: None,
    };
    let line = window
        .text_system()
        .shape_line(text.to_owned().into(), px(size), &[run], None);
    logical(line.width).ceil()
}

/// The least of a session's title its header keeps while the chips beside
/// it still have something to give: about a dozen letters.
const HEADER_TITLE_FLOOR: f32 = 96.0;
/// The least of a branch's name its chip shows: six letters and the
/// ellipsis. With less room than that the chip is its icon alone.
const BRANCH_CHIP_NAME_FLOOR: f32 = 52.0;
/// A header chip's padding at each end, and the gap after its icon.
const CHIP_PAD: f32 = 8.0;
const CHIP_GAP: f32 = 6.0;
const CHIP_ICON: f32 = 12.0;

/// What a session's header holds besides its title, as the widths each part
/// takes, so the header can tell what it has room for before it is drawn.
#[derive(Clone, Debug, Default, PartialEq)]
struct HeaderParts {
    /// The least of the title: [`HEADER_TITLE_FLOOR`], or all of a short one.
    title: f32,
    /// The assistant's chip as its mark alone, and what its name adds.
    agent: Option<(f32, f32)>,
    /// The branch chip as its icon alone, and what the least of its name
    /// adds: [`BRANCH_CHIP_NAME_FLOOR`], or all of a short name.
    branch: Option<(f32, f32)>,
    /// Each pull request chip, in order.
    pull_requests: Vec<f32>,
    /// What the pull requests need whatever else shows: the button that
    /// links one.
    pull_request_tools: f32,
    /// The status stamp.
    stamp: Option<f32>,
    /// The buttons at the right end, which always show.
    tools: f32,
}

/// What of a session's header fits the room it has. The side pane and
/// terminal buttons always do, and the title down to its floor. The rest
/// gives way in this order, the most dispensable first: pull request chips
/// one at a time, the branch's name and then the assistant's (their icons
/// stay), the status stamp (the chat's tab and the sidebar say it too), the
/// branch and the pull request button, and last the assistant's mark.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct HeaderFit {
    pull_requests: usize,
    branch_name: bool,
    agent_name: bool,
    stamp: bool,
    chips: bool,
    agent: bool,
}

impl HeaderParts {
    /// The header's padding at each side, and the gap between its parts.
    const PAD: f32 = 20.0;
    const GAP: f32 = 10.0;

    fn width(&self, fit: HeaderFit) -> f32 {
        let mut parts = vec![self.title, self.tools];
        if let Some((mark, name)) = self.agent.filter(|_| fit.agent) {
            parts.push(mark + if fit.agent_name { name } else { 0.0 });
        }
        if fit.chips {
            parts.extend(
                self.branch
                    .map(|(icon, name)| icon + if fit.branch_name { name } else { 0.0 }),
            );
            let shown = &self.pull_requests[..fit.pull_requests.min(self.pull_requests.len())];
            let more = shown.len() < self.pull_requests.len();
            let pieces =
                shown.len() + usize::from(more) + usize::from(self.pull_request_tools > 0.0);
            if pieces > 0 {
                parts.push(
                    shown.iter().sum::<f32>()
                        + if more { PULL_REQUESTS_MORE_WIDTH } else { 0.0 }
                        + self.pull_request_tools
                        + (pieces - 1) as f32 * CHIP_GAP,
                );
            }
        }
        parts.extend(self.stamp.filter(|_| fit.stamp));
        2.0 * Self::PAD + parts.iter().sum::<f32>() + (parts.len() - 1) as f32 * Self::GAP
    }

    fn fit(&self, room: f32) -> HeaderFit {
        let all = HeaderFit {
            pull_requests: self.pull_requests.len().min(HEADER_PULL_REQUEST_CHIPS),
            branch_name: true,
            agent_name: true,
            stamp: true,
            chips: true,
            agent: true,
        };
        let fewer = (0..all.pull_requests).rev().map(|pull_requests| HeaderFit {
            pull_requests,
            ..all
        });
        let none = HeaderFit {
            pull_requests: 0,
            ..all
        };
        let steps = [
            HeaderFit {
                branch_name: false,
                ..none
            },
            HeaderFit {
                branch_name: false,
                agent_name: false,
                ..none
            },
            HeaderFit {
                branch_name: false,
                agent_name: false,
                stamp: false,
                ..none
            },
            HeaderFit {
                branch_name: false,
                agent_name: false,
                stamp: false,
                chips: false,
                ..none
            },
        ];
        let least = HeaderFit {
            pull_requests: 0,
            branch_name: false,
            agent_name: false,
            stamp: false,
            chips: false,
            agent: false,
        };
        std::iter::once(all)
            .chain(fewer)
            .chain(steps)
            .find(|fit| self.width(*fit) <= room)
            .unwrap_or(least)
    }
}

/// The "+2" chip that stands for the pull requests the header does not show.
const PULL_REQUESTS_MORE_WIDTH: f32 = 34.0;

/// A header chip's width around a label `text` wide, after an icon.
fn chip_width(icon: f32, text: f32) -> f32 {
    2.0 * CHIP_PAD + icon + CHIP_GAP + text
}

/// The branch a session is on, in the session header. With `name_floor` it
/// shows the branch's name, cut short as the header narrows but never to
/// less than that much of it; without, it is its icon alone. A name cut to a
/// letter or two says nothing. The pointer reads the whole name either way.
///
/// It says what the session is on and does nothing when pressed, so it is
/// drawn as a label, not a button: no fill, no hover, no pointer. Its icon
/// alone is a Tab stop that shows the name under the ring, as under the
/// pointer.
fn branch_chip(
    branch: String,
    name_floor: Option<f32>,
    keys: &KeyTargets,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    let branch = SharedString::from(branch);
    let chip = static_chip("minimal-session-branch", colors)
        .font_family(MONO)
        .child(icon(GIT_BRANCH_ICON, CHIP_ICON, colors.muted));
    match name_floor {
        // The name's own tooltip reads it out while it is cut short.
        Some(floor) => chip
            .min_w(px(chip_width(CHIP_ICON, floor)))
            .flex_shrink()
            .child(truncating_label(branch).min_w_0()),
        None => static_chip_named(chip, "minimal-session-branch", branch, keys, colors),
    }
}

/// A chip of the session header that only says something, such as the
/// session's assistant or branch: its icon and words, set as a locked label
/// is, with nothing that looks pressable.
fn static_chip(id: &'static str, colors: ThemeColors) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .debug_selector(move || id.into())
        .h(hit_px(HIT_MIN))
        .px(px(CHIP_PAD))
        .flex()
        .items_center()
        .gap(px(CHIP_GAP))
        .cursor_default()
        .text_size(text_px(TEXT_LABEL))
        .text_color(rgb(colors.muted))
}

/// A static chip folded to its icon: the pointer reads its name, and so
/// does the keyboard, as a Tab stop that shows the name under its ring and
/// does nothing when pressed.
fn static_chip_named(
    chip: gpui::Stateful<gpui::Div>,
    id: &'static str,
    name: SharedString,
    keys: &KeyTargets,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    key_reach(
        chip.flex_none().tooltip(pane_tooltip(name.clone(), colors)),
        keys,
        KeyLayer::Page,
        id,
        Some(name),
        FOCUS_RING_RADIUS,
        colors,
        |_, _, _| {},
    )
}

/// The action a session row offers. While the pointer is over the row it
/// sits on top of the row's trailing label, so nothing on the row moves when
/// it appears. The open session's row has it in sight all the time, after
/// that label: without a pointer there is no hover to bring it out.
fn session_row_action(
    id: impl Into<gpui::ElementId>,
    label: &'static str,
    path: &'static str,
    selected: bool,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    let action = div().id(id);
    let action = if selected {
        // On a fill of its own, so it reads as a button beside the row's
        // status mark and not as one more mark.
        action
            .flex_none()
            .size(hit_px(HIT_MIN))
            .mr(px(-4.0))
            .bg(rgb(colors.border))
            .hover(|style| style.bg(rgb(colors.surface_high)))
    } else {
        action
            .invisible()
            .group_hover("catalog-session", |style| style.visible())
            .absolute()
            .right_0()
            .top_0()
            .bottom_0()
            .w(px(30.0))
            .bg(rgb(colors.surface_high))
    };
    action
        .flex()
        .items_center()
        .justify_center()
        .rounded(px(RADIUS_TAB))
        .cursor_pointer()
        .tooltip(pane_tooltip(label, colors))
        .child(icon(path, 13.0, colors.muted))
}

/// What the marks of [`drawer_tabs`] say, each once.
fn drawer_names(signals: &[SessionSignal]) -> Vec<String> {
    let mut names = Vec::new();
    for signal in signals
        .iter()
        .filter(|signal| **signal != SessionSignal::Idle)
        .take(5)
    {
        let name = signal.label().to_string();
        if !names.contains(&name) {
            names.push(name);
        }
    }
    names
}

/// The marks a collapsed project shows for its sessions that need a look.
fn drawer_tabs(signals: &[SessionSignal], colors: ThemeColors) -> gpui::AnyElement {
    div()
        .flex_none()
        .flex()
        .items_center()
        .gap(px(4.0))
        .children(
            signals
                .iter()
                .filter(|signal| **signal != SessionSignal::Idle)
                .take(5)
                .enumerate()
                .filter_map(|(index, signal)| {
                    let mark = status_mark(*signal, 6.0, colors)?;
                    Some(labelled_mark(
                        ("drawer-signal", index),
                        signal.label(),
                        colors,
                        mark,
                    ))
                }),
        )
        .into_any_element()
}

/// What an approval asks for, in the words of the tool asking.
fn approval_title(method: &str, tool: &str) -> String {
    match tool {
        "Bash" => "Run this command?".into(),
        "Edit" | "MultiEdit" | "NotebookEdit" => "Apply this edit?".into(),
        "Write" => "Write this file?".into(),
        "WebFetch" => "Fetch this page?".into(),
        "WebSearch" => "Search the web?".into(),
        "ExitPlanMode" => "Approve the plan?".into(),
        "" if method == "item/fileChange/requestApproval" => "Apply these changes?".into(),
        "" if method == "item/commandExecution/requestApproval" => "Run this command?".into(),
        "" => "Approval needed".into(),
        tool => format!("Allow {tool}?"),
    }
}

/// The first non-empty line of some markdown as plain text, for a one-line
/// preview: no heading or list markers, emphasis, or code ticks.
fn first_line(text: &str) -> String {
    text.lines()
        .map(|line| line.trim().trim_start_matches(['#', '-', '*', '>', ' ']))
        .find(|line| !line.is_empty() && !line.starts_with("```"))
        .unwrap_or_default()
        .replace("**", "")
        .replace("__", "")
        .replace('`', "")
}

/// A small status label on a soft tint of its own color.
/// The caption on a message sent in reply to a question.
fn answered_question_label(question: &str) -> String {
    format!("Answering “{}”", question.trim())
}

fn stamp(label: impl Into<SharedString>, color: u32, colors: ThemeColors) -> gpui::AnyElement {
    pill(label, color, colors)
}

fn pill(label: impl Into<SharedString>, color: u32, colors: ThemeColors) -> gpui::AnyElement {
    div()
        .flex_none()
        .px(px(7.0))
        .h(px(20.0))
        .flex()
        .items_center()
        .rounded_full()
        .bg(rgba((color << 8) | u32::from(colors.pill_alpha)))
        .text_size(text_px(TEXT_CAPTION))
        .font_weight(FontWeight::MEDIUM)
        .text_color(rgb(color))
        .child(label.into())
        .into_any_element()
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ButtonKind {
    Primary,
    Secondary,
    Ghost,
    Danger,
    /// A destructive choice offered beside others: danger text, no frame.
    DangerGhost,
}

/// The one button vocabulary used across the shell, popovers, and dialogs.
/// A button's size and type, with nothing that reacts to the pointer.
fn ui_button_shape(id: impl Into<gpui::ElementId>) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .h(px(CONTROL_HEIGHT))
        .px_3()
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(6.0))
        .rounded(px(RADIUS_CONTROL))
        .text_size(text_px(TEXT_CONTROL))
        .font_weight(FontWeight::MEDIUM)
}

fn ui_button(
    id: impl Into<gpui::ElementId>,
    kind: ButtonKind,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    let base = ui_button_shape(id).cursor_pointer();
    match kind {
        ButtonKind::Primary => base
            .bg(rgb(colors.accent))
            .text_color(rgb(colors.accent_text))
            .hover(|style| style.bg(rgb(colors.accent_hover))),
        ButtonKind::Secondary => base
            .border_1()
            .border_color(rgb(colors.control_border))
            .bg(rgb(colors.surface))
            .text_color(rgb(colors.text))
            .hover(|style| style.bg(rgb(colors.surface_high))),
        ButtonKind::Ghost => base.text_color(rgb(colors.muted)).hover(|style| {
            style
                .bg(rgb(colors.surface_high))
                .text_color(rgb(colors.text))
        }),
        ButtonKind::Danger => base
            .border_1()
            .border_color(rgb(colors.danger))
            .text_color(rgb(colors.danger))
            .hover(|style| style.bg(rgb(colors.danger_surface))),
        ButtonKind::DangerGhost => base
            .text_color(rgb(colors.danger))
            .hover(|style| style.bg(rgb(colors.danger_surface))),
    }
}

/// Which edge of a selected item its [`selection_marker`] stands on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MarkerEdge {
    /// The leading edge of a row in a list: the sidebar, Settings' sections.
    Leading,
    /// The foot of a tab or a segment.
    Foot,
}

/// How thick the selection marker is.
const SELECTION_MARKER: f32 = 2.0;
/// How far the marker stays from its item's corners.
const SELECTION_MARKER_INSET: f32 = 8.0;
/// How far left of a sidebar row its marker stands, in the gutter its list
/// keeps: clear of the chevron that folds a session's agents, which sits
/// at the row's leading edge.
const SIDEBAR_MARKER_GUTTER: f32 = 6.0;

/// What says an item is the selected one, beside its quiet fill: a 2px bar
/// in the selection colour, which stands at 3:1 or more against every
/// ground, just inside the item's leading edge or its foot. A child of the
/// item, drawn over its fill and taking no room.
fn selection_marker(edge: MarkerEdge, colors: ThemeColors) -> gpui::Div {
    let bar = div()
        .debug_selector(move || match edge {
            MarkerEdge::Leading => "selection-marker-leading".into(),
            MarkerEdge::Foot => "selection-marker-foot".into(),
        })
        .absolute()
        .rounded_full()
        .bg(rgb(colors.selected_border));
    match edge {
        MarkerEdge::Leading => bar
            .left_0()
            .top(px(SELECTION_MARKER_INSET))
            .bottom(px(SELECTION_MARKER_INSET))
            .w(px(SELECTION_MARKER)),
        MarkerEdge::Foot => bar
            .bottom_0()
            .left(px(SELECTION_MARKER_INSET))
            .right(px(SELECTION_MARKER_INSET))
            .h(px(SELECTION_MARKER)),
    }
}

/// A row of segments, one of them on: a choice of a few short words, such as
/// Usage's period and measure.
fn segmented_control() -> gpui::Div {
    div().flex().flex_none().items_center().gap(px(2.0))
}

/// The corners of a segment's focus ring: the segment's own, moved out.
const SEGMENT_RING_RADIUS: f32 = RADIUS_TAB + FOCUS_RING_GAP;
/// The corners of a tab's focus ring: the tab's own, moved out.
const TAB_RING_RADIUS: f32 = RADIUS_TAB + FOCUS_RING_GAP;

/// One segment of a [`segmented_control`], at the compact height, on a
/// selected fill while it is the one on.
fn segment_button(
    id: impl Into<gpui::ElementId>,
    label: impl Into<SharedString>,
    active: bool,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .h(px(CONTROL_HEIGHT_COMPACT))
        .px(px(9.0))
        .flex()
        .items_center()
        .rounded(px(RADIUS_TAB))
        .text_size(text_px(TEXT_LABEL))
        .font_weight(FontWeight::MEDIUM)
        .cursor_pointer()
        .text_color(rgb(if active { colors.text } else { colors.muted }))
        .when(active, |button| {
            button
                .bg(rgb(colors.selected_surface))
                .child(selection_marker(MarkerEdge::Foot, colors))
        })
        .when(!active, |button| {
            button.hover(|style| style.bg(rgb(colors.surface_high)))
        })
        .child(label.into())
}

/// A button that cannot be pressed now: the shape of [`ui_button`] with
/// [`disabled_edge`] and no fill, its words in [`disabled_ink`], and nothing
/// that reacts.
fn disabled_button(
    id: impl Into<gpui::ElementId>,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    disabled_edge(ui_button_shape(id), colors).text_color(rgb(disabled_ink(colors)))
}

/// What a control that cannot be used now is drawn in: the theme's disabled
/// ink, at 4.5:1 or more on every ground of both themes and, in Dark, 1.5:1
/// or more apart from the muted ink of a quiet control that can be used.
/// Nothing is dimmed by opacity, which let a disabled label fall under 3:1.
fn disabled_ink(colors: ThemeColors) -> u32 {
    colors.disabled
}

/// The edge that says a control cannot be used now, whatever its kind: a
/// dashed one in the control edge's ink, with no fill. No control that can
/// be used has a dashed edge, so this tells the two apart without the ink,
/// which Light cannot set far enough from its muted ink and keep readable.
fn disabled_edge<E: Styled>(control: E, colors: ThemeColors) -> E {
    control
        .border_1()
        .border_dashed()
        .border_color(rgb(colors.control_border))
}

/// [`ui_button`], or the same button while it cannot be pressed: nothing
/// reacts, its words are in [`disabled_ink`], and it takes
/// [`disabled_button`]'s dashed edge in place of any fill or frame.
fn ui_button_when(
    enabled: bool,
    id: impl Into<gpui::ElementId>,
    kind: ButtonKind,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    if enabled {
        ui_button(id, kind, colors)
    } else {
        disabled_button(id, colors)
    }
}

/// The one button that is an icon alone, so `label` names it under the
/// pointer: 28 by 28 around a 16px icon, or `size` around an icon in
/// proportion. One that cannot be used now keeps its place and its name and
/// is drawn in [`disabled_ink`], with nothing that reacts.
fn icon_button(
    id: impl Into<gpui::ElementId>,
    label: impl Into<SharedString>,
    path: &'static str,
    colors: ThemeColors,
) -> IconButton {
    IconButton {
        id: id.into(),
        label: label.into(),
        path,
        colors,
        size: CONTROL_HEIGHT_COMPACT,
        glyph: None,
        drawn: None,
        ink: None,
        wash: None,
        named: true,
        active: false,
        enabled: true,
    }
}

struct IconButton {
    id: gpui::ElementId,
    label: SharedString,
    path: &'static str,
    colors: ThemeColors,
    size: f32,
    glyph: Option<f32>,
    drawn: Option<fn(u32) -> gpui::AnyElement>,
    ink: Option<u32>,
    wash: Option<gpui::Rgba>,
    named: bool,
    active: bool,
    enabled: bool,
}

impl IconButton {
    fn size(mut self, size: f32) -> Self {
        self.size = size;
        self
    }

    /// The icon's own size, where the button's does not settle it.
    fn glyph(mut self, glyph: f32) -> Self {
        self.glyph = Some(glyph);
        self
    }

    /// A mark drawn in code in place of one from the icon set, such as the
    /// plus, in the ink it is handed.
    fn drawn(mut self, drawn: fn(u32) -> gpui::AnyElement) -> Self {
        self.drawn = Some(drawn);
        self
    }

    /// For a button drawn over a picture, not on the theme's ground: the
    /// icon's ink, with the fill under the pointer left to the caller unless
    /// [`Self::wash`] names one.
    fn ink(mut self, ink: u32) -> Self {
        self.ink = Some(ink);
        self
    }

    /// The fill under the pointer, for a button on a ground the usual fill
    /// would not show on: a row that is itself lit, or a tinted banner.
    fn wash(mut self, wash: impl Into<gpui::Rgba>) -> Self {
        self.wash = Some(wash.into());
        self
    }

    /// Whether the button shows its name under the pointer. A button holds
    /// it back while the menu it opened is up, which the name would cover.
    fn named(mut self, named: bool) -> Self {
        self.named = named;
        self
    }

    /// Lit, for a button whose pane or mode is the one showing.
    fn active(mut self, active: bool) -> Self {
        self.active = active;
        self
    }

    fn enabled(mut self, enabled: bool) -> Self {
        self.enabled = enabled;
        self
    }

    fn build(self) -> gpui::Stateful<gpui::Div> {
        let Self {
            id,
            label,
            path,
            colors,
            size,
            glyph,
            drawn,
            ink,
            wash,
            named,
            active,
            enabled,
        } = self;
        // 16px in the 28px button, 14px in a smaller one.
        let glyph = glyph.unwrap_or(if size < CONTROL_HEIGHT_COMPACT {
            14.0
        } else {
            16.0
        });
        let button = div()
            .id(id)
            .size(hit_px(size))
            .flex_none()
            .flex()
            .items_center()
            .justify_center()
            .rounded(px(RADIUS_CONTROL))
            .when(named, |button| button.tooltip(pane_tooltip(label, colors)));
        let mark = |ink: u32| match drawn {
            Some(drawn) => drawn(ink),
            None => icon(path, glyph, ink),
        };
        if !enabled {
            return disabled_edge(button, colors).child(mark(disabled_ink(colors)));
        }
        let button = button.cursor_pointer();
        if let Some(ink) = ink {
            return button
                .when_some(wash, |button, wash| {
                    button.hover(move |style| style.bg(wash))
                })
                .child(mark(ink));
        }
        let wash = wash.unwrap_or(rgb(colors.surface_high));
        button
            .when(active, |button| button.bg(rgb(colors.selected_surface)))
            .hover(move |style| style.bg(wash))
            .child(mark(if active { colors.text } else { colors.muted }))
    }
}

/// The two widths a dialog comes in: one for a question, a name or a short
/// list, and one for a form or a longer explanation.
const DIALOG_WIDTH: f32 = 450.0;
const DIALOG_WIDE_WIDTH: f32 = 480.0;
/// The room between a dialog field's name and its frame.
const DIALOG_LABEL_GAP: f32 = 6.0;

/// The layer a dialog is centred in: a backdrop over the whole window that
/// takes every click, with room left around the dialog.
fn dialog_layer(colors: ThemeColors) -> gpui::Div {
    div()
        .occlude()
        .absolute()
        .inset_0()
        .p_6()
        .flex()
        .items_center()
        .justify_center()
        .bg(rgba(colors.backdrop))
}

/// The frame every dialog is drawn in, at any width.
fn dialog_frame(colors: ThemeColors) -> gpui::Div {
    div()
        .rounded(px(DIALOG_RADIUS))
        .border_1()
        .border_color(rgb(colors.border))
        .bg(rgb(colors.surface))
        .shadow_lg()
}

/// The one dialog: a title, what it says or asks for, and its actions at the
/// bottom right. It never grows past the window: the part of it that can be
/// long scrolls inside it.
fn dialog_shell(width: f32, colors: ThemeColors) -> gpui::Div {
    dialog_frame(colors)
        .w(px(width))
        .max_w_full()
        .max_h_full()
        .min_h_0()
        .p_5()
        .flex()
        .flex_col()
        .gap_3()
        .text_color(rgb(colors.text))
        // A press on the dialog is not a press on the backdrop behind it.
        .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
}

/// The widths of a dialog that holds a page of its own: figures and a chart,
/// or a table to fill in.
const DIALOG_SHEET_WIDTH: f32 = 768.0;
const DIALOG_TABLE_WIDTH: f32 = 880.0;

/// A dialog that holds a page of its own, laid out by what it holds, in the
/// same frame as [`dialog_shell`], as wide as the window lets it be up to
/// `width`.
fn dialog_sheet(width: f32, colors: ThemeColors) -> gpui::Div {
    dialog_frame(colors)
        .w_full()
        .max_w(px(width))
        .max_h_full()
        .min_h_0()
        .flex()
        .flex_col()
}

fn dialog_title(title: impl Into<SharedString>, colors: ThemeColors) -> gpui::Div {
    div()
        .flex_none()
        .text_size(text_px(TEXT_HEADING))
        .font_weight(FontWeight::SEMIBOLD)
        .text_color(rgb(colors.text))
        .child(wrapped_heading(title))
}

/// How many headings [`wrapped_heading`] keeps the breaks of.
const HEADING_BREAKS_KEPT: usize = 64;

thread_local! {
    /// The headings drawn with their last word moved down to the mark that
    /// ends it, as last laid out: the text as written, and as drawn.
    static HEADING_BREAKS: RefCell<HashMap<SharedString, SharedString>> =
        RefCell::new(HashMap::new());
}

/// A heading that wraps, whose last line is never only the mark that ends
/// it. GPUI may break a line before any mark that is not part of a word, so
/// "rejected?" could wrap with its "?" alone on a line, and no joiner or
/// no-break space stops it: GPUI breaks before those too. Where the heading,
/// laid out at its width, would end that way, its last word goes down with
/// the mark, from the next frame on.
fn wrapped_heading(text: impl Into<SharedString>) -> gpui::Div {
    let text: SharedString = text.into();
    let shown = HEADING_BREAKS
        .with(|breaks| breaks.borrow().get(&text).cloned())
        .unwrap_or_else(|| text.clone());
    let drawn = shown.clone();
    div().relative().child(shown).child(
        canvas(
            move |bounds, window, _| {
                let look = TextLook::here(window);
                let broken = keep_last_word_with_its_mark(&text, bounds.size.width, &look, window);
                let wanted = broken.clone().unwrap_or_else(|| text.clone());
                HEADING_BREAKS.with(|breaks| {
                    let mut breaks = breaks.borrow_mut();
                    if breaks.len() >= HEADING_BREAKS_KEPT && !breaks.contains_key(&text) {
                        breaks.clear();
                    }
                    match broken {
                        Some(broken) => breaks.insert(text.clone(), broken),
                        None => breaks.remove(&text),
                    };
                });
                if wanted != drawn {
                    window.request_animation_frame();
                }
            },
            |_, _, _, _| {},
        )
        .absolute()
        .inset_0(),
    )
}

/// `text` with the space before its last word made a line break, when
/// laid out `width` wide its last line would hold nothing but the marks
/// that end it; `None` when it already ends well.
fn keep_last_word_with_its_mark(
    text: &str,
    width: Pixels,
    look: &TextLook,
    window: &Window,
) -> Option<SharedString> {
    let start = text.rfind('\n').map_or(0, |at| at + 1);
    let paragraph = &text[start..];
    let mut wrapper = window
        .text_system()
        .line_wrapper(look.font.clone(), look.size);
    let last = wrapper
        .wrap_line(&[gpui::LineFragment::text(paragraph)], width)
        .map(|boundary| boundary.ix)
        .last()?;
    let tail = paragraph.get(last..)?.trim();
    if tail.is_empty() || tail.chars().any(char::is_alphanumeric) {
        return None;
    }
    let space = paragraph[..last].trim_end().rfind(' ')?;
    let mut broken = text.to_owned();
    broken.replace_range(start + space..start + space + 1, "\n");
    Some(broken.into())
}

/// What a dialog says under its title.
fn dialog_text(text: impl Into<SharedString>, colors: ThemeColors) -> gpui::Div {
    div()
        .flex_none()
        .text_size(text_px(TEXT_BODY))
        .text_color(rgb(colors.muted))
        .child(text.into())
}

/// The row of a dialog's actions: the way out first, the main action last.
fn dialog_actions() -> gpui::Div {
    div().flex_none().mt_2().flex().justify_end().gap_2()
}

/// One of a dialog's actions: a [`ui_button`] Tab stops on. While it cannot
/// be pressed it is a [`disabled_button`], which Tab passes over.
#[allow(clippy::too_many_arguments)]
fn dialog_button(
    keys: &KeyTargets,
    id: &'static str,
    label: impl Into<SharedString>,
    kind: ButtonKind,
    enabled: bool,
    colors: ThemeColors,
    cx: &Context<XdDesktop>,
    run: impl Fn(&mut XdDesktop, &mut Window, &mut Context<XdDesktop>) + 'static,
) -> gpui::Stateful<gpui::Div> {
    let button = ui_button_when(enabled, id, kind, colors).child(label.into());
    if enabled {
        button.key_stop(keys, KeyLayer::Dialog, id, colors, cx, run)
    } else {
        button
    }
}

/// How near the window's edge a menu may come.
const MENU_MARGIN: f32 = 8.0;

/// The frame every menu and popover is drawn in. A press on it stays in it.
fn menu_shell(colors: ThemeColors) -> gpui::Div {
    div()
        .occlude()
        .p_1()
        .flex()
        .flex_col()
        .rounded(px(RADIUS_PANEL))
        .border_1()
        .border_color(rgb(colors.border))
        .bg(rgb(colors.surface))
        .shadow_lg()
        .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
        .on_mouse_down(MouseButton::Right, |_, _, cx| cx.stop_propagation())
}

/// One choice in a menu. It grows for a second line.
fn menu_row(id: impl Into<gpui::ElementId>, colors: ThemeColors) -> gpui::Stateful<gpui::Div> {
    menu_row_shape(id, colors).hover(|style| style.bg(rgb(colors.surface_high)))
}

/// A [`menu_row`] with no hover of its own, for a row that lights in another
/// fill, such as a destructive one, or not at all, as one that cannot be
/// picked now. GPUI takes one hover per element.
fn menu_row_shape(
    id: impl Into<gpui::ElementId>,
    colors: ThemeColors,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .w_full()
        .min_h(px(ROW_HEIGHT))
        .px(px(10.0))
        .flex_none()
        .flex()
        .items_center()
        .gap_2()
        .rounded(px(RADIUS_CONTROL))
        .text_size(text_px(TEXT_CONTROL))
        .text_color(rgb(colors.text))
        .cursor_pointer()
}

/// The room a menu row keeps for its check mark, and the mark on the choice
/// in force.
fn menu_check(checked: bool, colors: ThemeColors) -> gpui::Div {
    div().size(px(14.0)).flex_none().when(checked, |slot| {
        slot.child(icon(CHECK_ICON, 14.0, colors.text))
    })
}

/// A line of quiet text in a menu: a heading over its rows, or a note.
fn menu_note(label: impl IntoElement, colors: ThemeColors) -> gpui::Div {
    div()
        .px(px(10.0))
        .py(px(6.0))
        .text_size(text_px(TEXT_LABEL))
        .text_color(rgb(colors.muted))
        .child(label)
}

/// The hairline between a menu's groups.
fn menu_rule(colors: ThemeColors) -> gpui::Div {
    div().h(px(1.0)).my_1().flex_none().bg(rgb(colors.rule))
}

/// Hangs a menu from where this is placed, by `corner`, over everything
/// else, and moved as far as it takes to stay inside the window.
fn menu_popover(corner: gpui::Corner, menu: impl IntoElement) -> gpui::Deferred {
    gpui::deferred(
        gpui::anchored()
            .anchor(corner)
            .snap_to_window_with_margin(px(MENU_MARGIN))
            .child(menu),
    )
    .with_priority(1)
}

/// The gap between a control and the menu it opens.
const MENU_GAP: f32 = 4.0;

/// Hangs a menu from the control this is put in, as a direct child of a box
/// `control_height` tall that holds the control and nothing else in flow:
/// under the control, by its left or its right edge,
/// and above it where the window has no room below. The control is never
/// under its own menu, so the menu can be closed where it was opened.
///
/// The menu is anchored by its top to the control's top, behind an unseen
/// stand-in as tall as the control. Turned over to stand on that edge, it
/// ends where the control begins.
fn menu_under(corner: gpui::Corner, control_height: f32, menu: impl IntoElement) -> gpui::Div {
    let slot = div().absolute().top_0();
    let slot = if corner == gpui::Corner::TopRight {
        slot.right_0()
    } else {
        slot.left_0()
    };
    slot.child(
        gpui::deferred(
            gpui::anchored().anchor(corner).child(
                div()
                    .flex()
                    .flex_col()
                    .child(div().h(px(control_height)))
                    .child(div().py(px(MENU_GAP)).child(menu)),
            ),
        )
        .with_priority(1),
    )
}

/// The tallest a menu hung by [`menu_under`] may be and still fit on one
/// side of its control wherever the control is in the window; past that it
/// scrolls.
fn menu_under_max_height(control_height: f32, most: f32) -> f32 {
    let window = FRAME_VIEWPORT.with(Cell::get).1;
    (window / 2.0 - control_height - 2.0 * MENU_GAP).clamp(3.0 * ROW_HEIGHT, most)
}

/// The tallest a popover may be and still fit in the window inside its
/// margins; what it holds past that scrolls inside it.
fn popover_max_height() -> f32 {
    (FRAME_VIEWPORT.with(Cell::get).1 - 2.0 * MENU_MARGIN).max(3.0 * ROW_HEIGHT)
}

/// [`menu_popover`] at a point in the window, such as where the pointer was.
fn menu_at(position: Point<Pixels>, menu: impl IntoElement) -> gpui::Deferred {
    gpui::deferred(
        gpui::anchored()
            .position(position)
            .snap_to_window_with_margin(px(MENU_MARGIN))
            .child(menu),
    )
    .with_priority(1)
}

/// A drawn stroke icon from the embedded set, tinted to the surrounding text.
fn icon(path: &'static str, size: f32, color: u32) -> gpui::AnyElement {
    svg()
        .path(path)
        .size(px(size))
        .flex_none()
        .text_color(rgb(color))
        .into_any_element()
}

/// Assistant marks retain their brand color even in muted or selected rows.
fn assistant_icon(
    path: &'static str,
    size: f32,
    fallback: u32,
    colors: ThemeColors,
) -> gpui::AnyElement {
    let color = match path {
        CODEX_ICON => colors.codex_icon,
        CLAUDE_ICON => colors.claude_icon,
        _ => fallback,
    };
    icon(path, size, color)
}

/// A workspace's mark: the avatar of the account that owns it, and the folder
/// icon when there is no owner or no avatar to draw.
fn workspace_icon(avatar: Option<Arc<Image>>, size: f32, color: u32) -> gpui::AnyElement {
    match avatar {
        Some(avatar) => img(avatar)
            .size(px(size))
            .flex_none()
            .rounded(px(size / 4.0))
            .into_any_element(),
        None => icon(FOLDER_ICON, size, color),
    }
}

/// A context compaction in the conversation, as T3 Code draws it: a quiet
/// divider with the compaction's sentence in the middle, red if it failed and
/// breathing while it runs.
fn render_compaction_notice(
    id: impl Into<gpui::ElementId>,
    state: activity::CompactionState,
    label: &str,
    colors: ThemeColors,
) -> gpui::AnyElement {
    let failed = state == activity::CompactionState::Failed;
    let tone = if failed { colors.danger } else { colors.muted };
    let rule = || {
        div().h(px(1.0)).flex_1().min_w(px(24.0)).bg(rgb(if failed {
            colors.danger_surface
        } else {
            colors.border
        }))
    };
    let content = div()
        .id(id)
        .min_w_0()
        .flex()
        .items_center()
        .gap(px(6.0))
        .text_size(text_px(TEXT_LABEL))
        .text_color(rgb(tone))
        .child(icon(
            if failed { ALERT_ICON } else { COMPACT_ICON },
            12.0,
            tone,
        ))
        .child(div().min_w_0().truncate().child(label.to_owned()));
    // It breathes with the shared pulse, not a per-frame animation.
    let content = if state == activity::CompactionState::Running {
        content.opacity(pulse_opacity())
    } else {
        content
    };
    div()
        .w_full()
        .max_w(px(780.0))
        .py(px(6.0))
        .flex()
        .items_center()
        .gap(px(12.0))
        .child(rule())
        .child(content)
        .child(rule())
        .into_any_element()
}

/// The time the compact offer compares against, in Unix milliseconds.
fn compaction_clock_ms() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_millis() as i64)
}

struct PaneTooltip {
    label: SharedString,
    /// Quieter lines under the name, such as a figure's breakdown.
    detail: Vec<SharedString>,
    colors: ThemeColors,
}

/// What `.tooltip(…)` takes to name a control: every icon-only button has one.
fn pane_tooltip(
    label: impl Into<SharedString>,
    colors: ThemeColors,
) -> impl Fn(&mut Window, &mut App) -> gpui::AnyView + 'static {
    pane_tooltip_lines(vec![label.into()], colors)
}

/// [`pane_tooltip`] with quieter lines under its first: what a figure, a
/// bar or a row of Usage stands for.
fn pane_tooltip_lines(
    lines: Vec<SharedString>,
    colors: ThemeColors,
) -> impl Fn(&mut Window, &mut App) -> gpui::AnyView + 'static {
    move |_, cx| {
        let mut lines = lines.clone().into_iter();
        let label = lines.next().unwrap_or_default();
        let detail = lines.collect();
        cx.new(|_| PaneTooltip {
            label,
            detail,
            colors,
        })
        .into()
    }
}

/// The widest a tooltip grows before its words wrap.
const TOOLTIP_MAX_WIDTH: f32 = 400.0;

fn tooltip_box(label: impl Into<SharedString>, colors: ThemeColors) -> gpui::Div {
    div()
        .max_w(px(TOOLTIP_MAX_WIDTH))
        .px_2()
        .py_1()
        .flex()
        .flex_col()
        .gap(px(2.0))
        .rounded(px(RADIUS_CONTROL))
        .border_1()
        .border_color(rgb(colors.border))
        .bg(rgb(colors.surface_high))
        .text_size(text_px(TEXT_LABEL))
        .text_color(rgb(colors.text))
        .child(label.into())
}

impl Render for PaneTooltip {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        let muted = self.colors.muted;
        tooltip_box(self.label.clone(), self.colors).children(
            self.detail
                .iter()
                .map(|line| div().text_color(rgb(muted)).child(line.clone())),
        )
    }
}

/// The most of its list the Paired devices dialog shows before it scrolls,
/// which keeps the whole dialog inside the smallest window: five rows and
/// half of the next, its name cut through, so a longer list is seen to go on.
/// A row is its Revoke button, 30 high, and 8 above and below.
const PAIRED_DEVICES_LIST_HEIGHT: f32 = 5.5 * 46.0;

/// How far a [`ClearTooltip`] stays from the pointer, above or below it.
const CLEAR_TOOLTIP_GAP: f32 = 18.0;

/// A tooltip for a label, not a button: it explains the words under the
/// pointer, so it is held a line away from the pointer instead of over them.
/// GPUI opens a tooltip at the pointer, or just above it at the foot of the
/// window; the space around the box moves it clear either way.
struct ClearTooltip {
    label: SharedString,
    colors: ThemeColors,
}

impl Render for ClearTooltip {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        div()
            .py(px(CLEAR_TOOLTIP_GAP))
            .child(tooltip_box(self.label.clone(), self.colors))
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PatchLine {
    File,
    Added,
    Removed,
    Context,
    /// Hunk markers, and what git says about a file besides its lines.
    Detail,
}

/// A unified diff as a reader wants it: each file named once by its path, with
/// the object ids and repeated names left out. Only the headers before a file's
/// first hunk are dropped, so a removed `-- x` line can never be mistaken for one.
fn patch_view_lines(patch: &str) -> impl Iterator<Item = (PatchLine, &str)> {
    let mut in_header = false;
    patch.lines().filter_map(move |line| {
        if let Some(rest) = line.strip_prefix("diff --git ") {
            in_header = true;
            return Some((PatchLine::File, patch_file_path(rest)));
        }
        if line.starts_with("@@") {
            in_header = false;
            return Some((PatchLine::Detail, line));
        }
        if in_header {
            let repeated = ["index ", "--- ", "+++ "]
                .iter()
                .any(|prefix| line.starts_with(prefix));
            return (!repeated).then_some((PatchLine::Detail, line));
        }
        Some((
            match line.as_bytes().first() {
                Some(b'+') => PatchLine::Added,
                Some(b'-') => PatchLine::Removed,
                _ => PatchLine::Context,
            },
            line,
        ))
    })
}

/// How many of a patch's lines the Changes pane draws. A longer patch ends with
/// a line that says so.
const PATCH_VIEW_LINES: usize = 4_000;

/// One row of the Changes pane.
#[derive(Clone, Debug, PartialEq, Eq)]
enum PatchRow {
    Line(PatchLine, SharedString),
    /// The space above every file but the first.
    Gap,
    /// Closes a patch that was cut at [`PATCH_VIEW_LINES`].
    Cut,
}

/// A patch as the Changes pane's rows, built once when the patch arrives so a
/// frame draws only the rows in view and never reads the patch again.
#[derive(Clone, Default)]
struct PatchView {
    rows: Rc<[PatchRow]>,
    /// The row with the most text, which sets how far the pane scrolls sideways.
    widest: Option<usize>,
}

impl PatchView {
    fn new(patch: &str) -> Self {
        let mut lines = patch_view_lines(patch);
        let mut rows = Vec::new();
        let mut widest: Option<(usize, usize)> = None;
        for (kind, line) in lines.by_ref().take(PATCH_VIEW_LINES) {
            if kind == PatchLine::File && !rows.is_empty() {
                rows.push(PatchRow::Gap);
            }
            let width = line.chars().count();
            if widest.is_none_or(|(_, most)| width > most) {
                widest = Some((rows.len(), width));
            }
            rows.push(PatchRow::Line(kind, SharedString::new(line)));
        }
        if lines.next().is_some() {
            rows.push(PatchRow::Cut);
        }
        Self {
            rows: rows.into(),
            widest: widest.map(|(index, _)| index),
        }
    }

    fn is_empty(&self) -> bool {
        self.rows.is_empty()
    }
}

/// Whether the Changes pane can commit, and what to tell the user when not.
#[derive(Clone, Debug, PartialEq, Eq)]
enum CommitState {
    Ready,
    /// A Git operation is running; the button shows what it is.
    Busy(String),
    /// Nothing to press, with the reason for the button's tooltip.
    Blocked(&'static str),
}

impl CommitState {
    fn of(diff: &DiffPanel, message: &str) -> Self {
        if let Some(action) = &diff.action {
            return Self::Busy(action.clone());
        }
        match &diff.status {
            None => Self::Blocked("Checking for changes…"),
            Some(status) if status.conflicted > 0 => Self::Blocked("Resolve the conflicts first."),
            Some(status) if status.clean => Self::Blocked("No changes to commit."),
            Some(_) if message.trim().is_empty() => Self::Blocked("Enter a commit message."),
            Some(_) => Self::Ready,
        }
    }
}

/// The line above the commit box: what went wrong last, or what stands in the
/// way of a commit that the user has to deal with outside this pane.
fn commit_notice(diff: &DiffPanel) -> Option<String> {
    if let Some(error) = &diff.action_error {
        return Some(error.clone());
    }
    match diff.status.as_ref()?.conflicted {
        0 => None,
        1 => Some("1 file is in conflict. Resolve it to commit.".into()),
        files => Some(format!(
            "{files} files are in conflict. Resolve them to commit."
        )),
    }
}

/// The height every row of the Changes pane shares, so only those in view are
/// laid out.
const PATCH_ROW_HEIGHT: f32 = 19.0;

fn patch_row(row: &PatchRow, colors: ThemeColors) -> gpui::Div {
    // As wide as the pane, or the part of the patch scrolled into view, so a
    // row's fill reaches the pane's edge.
    let base = div()
        .w_full()
        .h(px(PATCH_ROW_HEIGHT))
        .px_3()
        .flex()
        .items_center()
        .whitespace_nowrap()
        .font_family(MONO)
        .text_size(text_px(TEXT_MONO));
    let (kind, line) = match row {
        PatchRow::Gap => return base,
        PatchRow::Cut => {
            return base
                .font_family(UI_FONT)
                .text_color(rgb(colors.muted))
                .child(format!(
                    "Showing the first {} lines.",
                    xd_desktop::usage::format_count(PATCH_VIEW_LINES as u64)
                ));
        }
        PatchRow::Line(kind, line) => (*kind, line.clone()),
    };
    let (fg, bg) = match kind {
        PatchLine::File => (colors.text, Some(colors.surface_high)),
        PatchLine::Added => (colors.text, Some(colors.diff_added)),
        PatchLine::Removed => (colors.text, Some(colors.diff_removed)),
        PatchLine::Context => (colors.muted, None),
        PatchLine::Detail => (colors.faint, None),
    };
    base.text_color(rgb(fg))
        .when_some(bg, |row, bg| row.bg(rgb(bg)))
        .when(kind == PatchLine::File, |row| {
            row.font_weight(FontWeight::MEDIUM)
        })
        .child(if line.is_empty() {
            SharedString::new_static(" ")
        } else {
            line
        })
}

/// The newer path in `a/old b/new`. An unrenamed file repeats one path, which
/// splits exactly even if the path contains ` b/`; a rename's own lines stay in
/// the patch, naming it in full. Other prefixes, and quoted paths git could not
/// write plainly, are shown as git wrote them.
fn patch_file_path(paths: &str) -> &str {
    let unrenamed = paths.len().checked_sub(5).and_then(|names| {
        let name = paths.strip_prefix("a/")?.get(..names / 2)?;
        (paths.len() % 2 == 1 && paths[2 + name.len()..].strip_prefix(" b/")? == name)
            .then_some(name)
    });
    unrenamed.unwrap_or_else(|| {
        paths
            .strip_prefix("a/")
            .and_then(|_| paths.rsplit_once(" b/"))
            .map_or(paths, |(_, new)| new)
    })
}

fn agent_icon(agent: AgentCli) -> &'static str {
    match agent {
        AgentCli::Codex => CODEX_ICON,
        AgentCli::Claude => CLAUDE_ICON,
        AgentCli::Other => TERMINAL_ICON,
    }
}

