struct TerminalPanel {
    chat_id: String,
    workdir: Option<String>,
    agent: Option<AgentCli>,
    allow_agent_tabs: bool,
    sessions: Vec<TerminalTab>,
    selected: Option<String>,
    viewport: Option<(usize, usize)>,
    auto_open: bool,
    opening: bool,
    opening_agent: Option<AgentCli>,
    opening_generation: u64,
    loading: bool,
    pending_events: Vec<PendingTerminalEvent>,
    error: Option<String>,
}

impl TerminalPanel {
    fn accepts_agent(&self, agent: Option<AgentCli>) -> bool {
        self.allow_agent_tabs || self.agent == agent
    }

    fn opening_matches_protocol_agent(&self, agent: Option<&str>) -> bool {
        if !self.opening {
            return false;
        }
        match (agent, self.opening_agent) {
            (None, None) => true,
            (Some(protocol), Some(agent)) => protocol == agent.protocol_name(),
            _ => false,
        }
    }

    fn finish_opening(&mut self) {
        self.opening = false;
        self.opening_agent = None;
    }

    fn begin_opening(&mut self, agent: Option<AgentCli>) -> u64 {
        self.opening_generation = self.opening_generation.wrapping_add(1);
        self.opening = true;
        self.opening_agent = agent;
        self.opening_generation
    }

    fn expire_opening(&mut self, generation: u64) -> bool {
        if !self.opening || self.opening_generation != generation {
            return false;
        }
        self.finish_opening();
        true
    }

    /// Whether closing this tab would leave the panel with nothing to show.
    fn is_only_tab(&self, terminal_id: &str) -> bool {
        !self.opening && matches!(self.sessions.as_slice(), [session] if session.id == terminal_id)
    }

    fn selected(&self) -> Option<&TerminalTab> {
        let selected = self.selected.as_deref()?;
        self.sessions.iter().find(|session| session.id == selected)
    }

    fn has_requested_session(&self) -> bool {
        self.sessions
            .iter()
            .any(|session| session.agent == self.agent)
    }

    fn should_auto_open(&self) -> bool {
        !self.loading && !self.has_requested_session() && self.auto_open && !self.opening
    }

    fn selection_after_refresh(&self, previous: Option<String>) -> Option<String> {
        previous
            .filter(|selected| self.sessions.iter().any(|session| &session.id == selected))
            .or_else(|| {
                self.sessions
                    .iter()
                    .find(|session| session.agent == self.agent)
                    .map(|session| session.id.clone())
            })
            .or_else(|| self.sessions.first().map(|session| session.id.clone()))
    }

    fn selected_mut(&mut self) -> Option<&mut TerminalTab> {
        let selected = self.selected.as_deref()?;
        self.sessions
            .iter_mut()
            .find(|session| session.id == selected)
    }

    fn remove(&mut self, terminal_id: &str) {
        self.sessions
            .retain(|session| session.id.as_str() != terminal_id);
        if self.selected.as_deref() == Some(terminal_id) {
            self.selected = self.sessions.first().map(|session| session.id.clone());
        }
    }
}

#[allow(dead_code)]
fn terminal_tab_title(agent: Option<AgentCli>) -> String {
    agent.map(AgentCli::label).unwrap_or("Terminal").to_owned()
}

fn terminal_runtime_event(event: SessionEvent) -> (ChatEndpoint, &'static str, Value) {
    let endpoint = event.endpoint().into();
    let (name, body) = match event.kind {
        SessionEventKind::Opened {
            chat_id,
            terminal_id,
            title,
            agent,
            columns,
            rows,
        } => (
            "terminal-opened",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "title": title,
                "agent": agent,
                "columns": columns,
                "rows": rows,
            }),
        ),
        SessionEventKind::Output {
            chat_id,
            terminal_id,
            data,
        } => (
            "terminal-output",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "data": STANDARD.encode(data),
            }),
        ),
        SessionEventKind::Resized {
            chat_id,
            terminal_id,
            columns,
            rows,
        } => (
            "terminal-resized",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "columns": columns,
                "rows": rows,
            }),
        ),
        SessionEventKind::Activity {
            chat_id,
            terminal_id,
            working,
        } => (
            "terminal-activity",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "working": working,
                "terminal_working": working,
            }),
        ),
        SessionEventKind::Closed {
            chat_id,
            terminal_id,
        } => (
            "terminal-closed",
            serde_json::json!({"chat": chat_id, "terminal": terminal_id}),
        ),
    };
    (endpoint, name, body)
}

/// The thumb that shows a scroll area's place: this wide, this far in from
/// its right edge, and never shorter than this.
const SCROLL_THUMB_WIDTH: f32 = 4.0;
const SCROLL_THUMB_INSET: f32 = 2.0;
const SCROLL_THUMB_MIN_HEIGHT: f32 = 24.0;
/// What an area may run past its view without a thumb: the reach of a row
/// into the padding around it, not content out of sight.
const SCROLL_THUMB_SLACK: f32 = 8.0;
/// Past this many, the handles of scroll areas no longer drawn are let go.
const SCROLL_HANDLES_KEPT: usize = 512;

thread_local! {
    /// The scroll of each area that has no handle of its own, by its key, so
    /// its thumb can read where it is.
    static SCROLL_HANDLES: RefCell<HashMap<SharedString, ScrollHandle>> =
        RefCell::new(HashMap::new());
}

/// The scroll handle kept for the area `key` names.
fn scroll_handle_for(key: impl Into<SharedString>) -> ScrollHandle {
    let key = key.into();
    SCROLL_HANDLES.with(|handles| {
        let mut handles = handles.borrow_mut();
        if handles.len() > SCROLL_HANDLES_KEPT && !handles.contains_key(&key) {
            handles.clear();
        }
        handles.entry(key).or_default().clone()
    })
}

/// Where a thumb sits, from a scroll area's view, how far its content runs
/// past the view, and how far it is scrolled, all in the window's pixels.
/// `None` while everything fits.
fn scroll_thumb_bounds(
    view: Bounds<Pixels>,
    overflow: Pixels,
    scrolled: Pixels,
) -> Option<Bounds<Pixels>> {
    let height = view.size.height;
    if overflow <= px(SCROLL_THUMB_SLACK) || height <= gpui::px(0.0) {
        return None;
    }
    let thumb = (height * (height / (height + overflow)))
        .max(px(SCROLL_THUMB_MIN_HEIGHT))
        .min(height);
    let progress = (scrolled / overflow).clamp(0.0, 1.0);
    let top = view.top() + (height - thumb) * progress;
    let width = px(SCROLL_THUMB_WIDTH);
    Some(Bounds::new(
        point(view.right() - width - px(SCROLL_THUMB_INSET), top),
        size(width, thumb),
    ))
}

fn paint_scroll_thumb(bounds: Option<Bounds<Pixels>>, colors: ThemeColors, window: &mut Window) {
    if let Some(bounds) = bounds {
        window.paint_quad(
            gpui::fill(bounds, rgba(colors.scroll_thumb))
                .corner_radii(px(SCROLL_THUMB_WIDTH / 2.0)),
        );
    }
}

/// A thin thumb at the right edge of the scroll area `handle` tracks, while
/// its content overflows: where it is, and that there is more. It takes no
/// room and no clicks. A child of that area.
fn scroll_thumb(handle: ScrollHandle, colors: ThemeColors) -> impl IntoElement {
    canvas(
        |_, _, _| {},
        move |_, _, window, _| {
            let bounds = scroll_thumb_bounds(
                handle.bounds(),
                handle.max_offset().height,
                -handle.offset().y,
            );
            paint_scroll_thumb(bounds, colors, window);
        },
    )
    .absolute()
    .top_0()
    .left_0()
    .size_0()
}

/// [`scroll_thumb`] for a list of rows measured as they show, such as the
/// transcript. A list pinned to its end keeps its scroll top past its last
/// row, so the thumb is placed by where its top really is.
fn list_scroll_thumb(list: ListState, colors: ThemeColors) -> impl IntoElement {
    canvas(
        |_, _, _| {},
        move |_, _, window, _| {
            let overflow = list.max_offset_for_scrollbar().height;
            let scrolled = (-list.scroll_px_offset_for_scrollbar().y).min(overflow);
            let bounds = scroll_thumb_bounds(list.viewport_bounds(), overflow, scrolled);
            paint_scroll_thumb(bounds, colors, window);
        },
    )
    .absolute()
    .top_0()
    .left_0()
    .size_0()
}

/// A scroll area with a thumb that shows its place.
trait ScrollThumb: Sized {
    /// Tracks the area with `handle` and draws its thumb.
    fn scroll_thumb(self, handle: &ScrollHandle, colors: ThemeColors) -> Self;

    /// The same, with a handle kept for `key`, for an area without one.
    fn thumbed(self, key: impl Into<SharedString>, colors: ThemeColors) -> Self {
        let handle = scroll_handle_for(key);
        self.scroll_thumb(&handle, colors)
    }
}

impl ScrollThumb for gpui::Stateful<gpui::Div> {
    fn scroll_thumb(self, handle: &ScrollHandle, colors: ThemeColors) -> Self {
        self.track_scroll(handle)
            .child(scroll_thumb(handle.clone(), colors))
    }
}

/// How many delegated agents' reports stay parsed between frames.
const REPORT_CACHE_SIZE: usize = 64;

thread_local! {
    /// Reports and latest messages of delegated agents, parsed once for each
    /// text. Their cards redraw with every pulse while agents work, and a
    /// report seldom changes between two.
    static PARSED_REPORTS: RefCell<HashMap<String, Rc<markdown::Document>>> =
        RefCell::new(HashMap::new());
    /// How many reports were parsed, which the tests count.
    static REPORT_PARSES: Cell<usize> = const { Cell::new(0) };
}

/// A delegated agent's report, parsed as markdown once for each text.
fn parsed_report(report: &str) -> Rc<markdown::Document> {
    PARSED_REPORTS.with(|cache| {
        if let Some(document) = cache.borrow().get(report) {
            return document.clone();
        }
        REPORT_PARSES.with(|parses| parses.set(parses.get() + 1));
        let document = Rc::new(markdown::parse_assistant(report));
        let mut cache = cache.borrow_mut();
        if cache.len() >= REPORT_CACHE_SIZE {
            // Reports from long ago are cheap to parse again.
            cache.clear();
        }
        cache.insert(report.to_owned(), document.clone());
        document
    })
}

/// One line of the shown terminal as it is drawn: its text, colours, cursor
/// and links, ranges counted from the line's start.
struct TerminalRow {
    text: SharedString,
    highlights: Vec<(Range<usize>, HighlightStyle)>,
    cursor: Option<Range<usize>>,
    /// The cursor's fill and ink where its cell has a background of its
    /// own, such as a selection in inverse video: the cell's colours the
    /// other way round, so the cursor shows on it. Elsewhere it is drawn in
    /// the theme's text colour on the ground.
    cursor_colors: Option<(u32, u32)>,
    links: Vec<(Range<usize>, String)>,
}

impl TerminalRow {
    fn new(rendered: TerminalText) -> Self {
        let mut links = rendered
            .links
            .into_iter()
            .map(|link| (link.range, link.url))
            .collect::<Vec<_>>();
        let detected = markdown::web_links(&rendered.text)
            .into_iter()
            .filter(|(range, _)| {
                !links
                    .iter()
                    .any(|(native, _)| native.start < range.end && range.start < native.end)
            })
            .collect::<Vec<_>>();
        links.extend(detected);
        links.sort_by_key(|(range, _)| range.start);
        let cursor_colors = rendered.cursor.as_ref().and_then(|cursor| {
            let span = rendered
                .spans
                .iter()
                .find(|span| span.range.start <= cursor.start && cursor.start < span.range.end)?;
            Some((span.style.foreground?, span.style.background?))
        });
        let highlights = rendered
            .spans
            .into_iter()
            .map(|span| (span.range, terminal_highlight(span.style)))
            .collect();
        Self {
            text: rendered.text.into(),
            highlights,
            cursor: rendered.cursor,
            cursor_colors,
            links,
        }
    }
}

/// How a run of the terminal's cells is drawn. Inverse video, dim and
/// hidden text come worked into the colours. The bundled JetBrains Mono has
/// no italic, so italic text stays upright rather than fall back to another
/// face out of the grid.
fn terminal_highlight(style: xd_terminal::TerminalStyle) -> HighlightStyle {
    HighlightStyle {
        color: style.foreground.map(|color| rgb(color).into()),
        background_color: style.background.map(|color| rgb(color).into()),
        font_weight: style.bold.then_some(FontWeight::BOLD),
        underline: style.underline.then(|| gpui::UnderlineStyle {
            thickness: px(1.0),
            color: None,
            wavy: false,
        }),
        strikethrough: style.strikethrough.then(|| gpui::StrikethroughStyle {
            thickness: px(1.0),
            color: None,
        }),
        ..Default::default()
    }
}

/// How many built rows the shown terminal keeps before it starts again.
const TERMINAL_ROW_CACHE: usize = 1024;

/// The shown terminal's rows, built only as they come into view. A row is
/// kept by its fingerprint, what it draws, so new output or a scroll builds
/// only the rows that changed or came into view, never the whole
/// scrollback; a new palette builds them again.
#[derive(Default)]
struct TerminalRows {
    /// The terminal and screen revision `count` was taken at.
    terminal: Option<String>,
    revision: u64,
    palette: TerminalPalette,
    count: usize,
    built: HashMap<u64, Rc<TerminalRow>>,
}

thread_local! {
    /// How many terminal rows were built, which the tests count.
    static TERMINAL_ROWS_BUILT: Cell<usize> = const { Cell::new(0) };
}

fn insert_terminal_cursor_highlight(
    highlights: Vec<(Range<usize>, HighlightStyle)>,
    cursor: Option<(Range<usize>, HighlightStyle)>,
) -> Vec<(Range<usize>, HighlightStyle)> {
    let Some((cursor_range, cursor_style)) = cursor else {
        return highlights;
    };
    if cursor_range.is_empty() {
        return highlights;
    }

    let mut result = Vec::with_capacity(highlights.len() + 2);
    let mut inserted = false;
    for (range, style) in highlights {
        if range.end <= cursor_range.start {
            result.push((range, style));
        } else if cursor_range.end <= range.start {
            if !inserted {
                result.push((cursor_range.clone(), cursor_style));
                inserted = true;
            }
            result.push((range, style));
        } else {
            if range.start < cursor_range.start {
                result.push((range.start..cursor_range.start, style));
            }
            if !inserted {
                result.push((cursor_range.clone(), cursor_style));
                inserted = true;
            }
            if cursor_range.end < range.end {
                result.push((cursor_range.end..range.end, style));
            }
        }
    }
    if !inserted {
        result.push((cursor_range, cursor_style));
    }
    result
}

const TERMINAL_OUTPUT_PADDING: f32 = 16.0;

fn terminal_geometry(width: f32, height: f32, cell_width: f32, line_height: f32) -> (usize, usize) {
    let total_padding = TERMINAL_OUTPUT_PADDING * 2.0;
    let content_width = (width - total_padding).max(cell_width);
    let content_height = (height - total_padding).max(line_height);
    let columns = (content_width / cell_width.max(1.0)).floor() as usize;
    let rows = (content_height / line_height.max(1.0)).floor() as usize;
    (columns.clamp(20, 500), rows.clamp(4, 200))
}

fn terminal_scroll_is_at_bottom(scroll: &ScrollHandle) -> bool {
    let remaining = logical(scroll.max_offset().height) + logical(scroll.offset().y);
    remaining <= 2.0
}

fn terminal_mouse_scroll_bytes(delta_y: f32) -> Vec<u8> {
    let button = if delta_y > 0.0 {
        64
    } else if delta_y < 0.0 {
        65
    } else {
        return Vec::new();
    };
    format!("\x1b[<{button};1;1M").into_bytes()
}

#[derive(Clone, Debug, Default, Deserialize)]
struct GitStatus {
    branch: String,
    #[serde(default)]
    base: String,
    upstream: String,
    ahead: u64,
    conflicted: u64,
    clean: bool,
}

impl GitStatus {
    fn can_open_pull_request(&self) -> bool {
        self.clean
            && self.conflicted == 0
            && !self.branch.is_empty()
            && !matches!(self.branch.as_str(), "(detached)" | "(initial)")
            && !self.base.is_empty()
            && self.branch != self.base
            && !self.upstream.is_empty()
            && self.ahead == 0
    }
}

/// How long the session header trusts what it knows about a pull request. An
/// agent can open one from a terminal without the app hearing about it.
const CHAT_PULL_REQUEST_LIFETIME: Duration = Duration::from_secs(60);

/// What a host last said about the pull request of a chat's branch.
#[derive(Default)]
struct ChatPullRequest {
    requested_at: Option<Instant>,
    lookups: u64,
    branch: Option<String>,
    url: Option<String>,
}

impl ChatPullRequest {
    fn lookup_due(&self, now: Instant) -> bool {
        self.requested_at
            .is_none_or(|at| now.duration_since(at) >= CHAT_PULL_REQUEST_LIFETIME)
    }

    /// Starts a lookup, superseding any still running, and returns its token.
    fn start_lookup(&mut self, now: Instant) -> String {
        self.requested_at = Some(now);
        self.lookups += 1;
        self.lookup_token()
    }

    /// Hosts broadcast these answers, so the token also says which client asked.
    fn lookup_token(&self) -> String {
        static CLIENT: std::sync::OnceLock<u64> = std::sync::OnceLock::new();
        let client = CLIENT.get_or_init(|| {
            use std::hash::BuildHasher;
            std::collections::hash_map::RandomState::new().hash_one(std::process::id())
        });
        format!("pull-request-{client:x}-{}", self.lookups)
    }

    /// Lookups overlap and can finish in any order, so only the latest counts.
    /// A failed lookup says nothing, so it keeps the branch's known pull request.
    fn apply(&mut self, lookup: Option<&str>, answer: &Value) {
        if lookup != Some(self.lookup_token().as_str()) {
            return;
        }
        let Some(branch) = answer.get("branch").and_then(Value::as_str) else {
            return;
        };
        let same_branch = self.branch.as_deref() == Some(branch);
        match answer.get("url").and_then(Value::as_str) {
            Some(url) => self.url = (!url.is_empty()).then(|| url.to_owned()),
            None if !same_branch => self.url = None,
            None => {}
        }
        if !same_branch {
            self.branch = Some(branch.to_owned());
        }
    }

    fn url_for(&self, branch: &str) -> Option<&str> {
        (self.branch.as_deref() == Some(branch))
            .then_some(self.url.as_deref())
            .flatten()
    }
}

/// `#123` for a pull request's web address, or `PR` when it has no number in it.
fn pull_request_label(url: &str) -> String {
    let number = url
        .rsplit_once("/pull/")
        .map(|(_, rest)| {
            rest.chars()
                .take_while(char::is_ascii_digit)
                .collect::<String>()
        })
        .unwrap_or_default();
    if number.is_empty() {
        "PR".into()
    } else {
        format!("#{number}")
    }
}

/// How many linked pull requests the session header names before `+N`.
const HEADER_PULL_REQUEST_CHIPS: usize = 3;

const NOT_A_PULL_REQUEST_LINK: &str = "That is not a pull request link.";

/// The session header's "Pull requests" popover, for one chat on one host.
struct PullRequestPanel {
    endpoint: ChatEndpoint,
    chat_id: String,
    text: String,
    /// The link request still awaiting its answer.
    linking: Option<u64>,
    /// The field's text when that request went out. Its answer rewrites the
    /// field only if the user has not typed since.
    sent: String,
    error: Option<String>,
}

/// Tints a pull request's icon by its state, so merged and closed ones read
/// apart from open ones at a glance.
fn pull_request_state_color(state: Option<PullRequestState>, colors: ThemeColors) -> u32 {
    match state {
        Some(PullRequestState::Open) => colors.working,
        Some(PullRequestState::Merged) => colors.done,
        Some(PullRequestState::Closed) => colors.danger,
        None => colors.muted,
    }
}

fn pull_request_state_label(state: PullRequestState) -> &'static str {
    match state {
        PullRequestState::Open => "Open",
        PullRequestState::Merged => "Merged",
        PullRequestState::Closed => "Closed",
    }
}

fn pull_request_chip_tooltip(state: Option<PullRequestState>) -> &'static str {
    match state {
        Some(PullRequestState::Merged) => "Open pull request (merged)",
        Some(PullRequestState::Closed) => "Open pull request (closed)",
        Some(PullRequestState::Open) | None => "Open pull request",
    }
}

/// How many addresses a host links in one request.
const MAX_PULL_REQUESTS_PER_LINK: usize = 16;
/// How many rows the Pull requests popover shows before its list scrolls.
const PULL_REQUEST_PANEL_MAX_ROWS: f32 = 8.0;

/// The addresses in what was pasted into the link field: one or several,
/// apart by spaces, commas or lines.
fn pasted_pull_request_urls(text: &str) -> Vec<String> {
    text.split(|c: char| c.is_whitespace() || c == ',')
        .filter(|url| !url.is_empty())
        .map(str::to_owned)
        .collect()
}

