#[derive(Clone, Copy)]
enum OptimisticSend {
    Started { message_index: Option<usize> },
    Queued,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct OpenQuestion {
    chat_id: String,
    question: String,
    options: Vec<String>,
    accepts_input: bool,
}

/// What a chat's composer can have docked at its top while the chat waits on
/// the user.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DockedAsk {
    /// An approval, or a request for input, from the running turn.
    Interaction,
    /// The chat stopped at its quota.
    Quota,
    /// The agent's reply ended in a tagged question.
    Question,
}

/// Where an answer to the docked question goes.
#[derive(Clone, Debug, PartialEq, Eq)]
enum AskAnswer {
    /// The reply's tagged question: the answer is the next message.
    Tagged,
    /// A question in a request for input.
    Interaction {
        request_id: String,
        question_id: String,
    },
    /// An approval: the answer is one of [`APPROVAL_DECISIONS`].
    Approval { request_id: String },
}

/// An approval's answers, in the order they are drawn and numbered: what
/// each button says, and the decision it sends. The first is what Enter
/// takes once the keyboard is in the approval; nothing is ever approved
/// without a key or a click on one of them.
const APPROVAL_DECISIONS: [(&str, &str); 3] = [
    ("Allow once", "accept"),
    ("Allow for session", "acceptForSession"),
    ("Deny", "decline"),
];

/// What taking an answer came to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Answered {
    /// Not taken: nothing to answer, or it could not be sent.
    No,
    /// Kept for the request's other questions.
    Kept,
    /// Sent to the host, which has yet to take it.
    Sent,
}

/// One request for input: the host it came from, its chat, and its id. The
/// host is named as `XdDesktop::host_identity` does, so a request on one host
/// is never taken for another's with the same ids.
#[derive(Clone, Debug, Hash, PartialEq, Eq)]
struct InteractionKey {
    host: String,
    chat_id: String,
    request_id: String,
}

/// What the user has answered of one request for input. It lasts until the
/// request is settled, whichever chat is open meanwhile, and goes with its
/// host's connection.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RequestAnswers {
    /// Answers kept by question id while the request's other questions wait.
    answers: HashMap<String, String>,
    /// Set once every question is answered and the response is on its way,
    /// until the host replies to it. Its last question stays open but cannot
    /// be answered again meanwhile, so a refusal gives it back rather than
    /// leaving a request nothing can answer.
    submit: Option<InteractionSubmit>,
    /// The host took the response; the request goes once it is resolved.
    accepted: bool,
    /// The request was resolved or cleared while its response was on its
    /// way; only the reply is still awaited.
    resolved: bool,
}

/// A request's answers on their way to the host.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct InteractionSubmit {
    /// The composer's words it answered with, which left the composer as a
    /// sent message's do, and come back if the host refuses them.
    typed: Option<String>,
}

/// The docked question's choices: each answer, with a description when the
/// agent gave one.
struct AskChoices {
    /// Which question these belong to.
    key: String,
    target: AskAnswer,
    choices: Vec<(String, Option<String>)>,
}

impl AskChoices {
    /// An approval's buttons stand in a row under it, the first nearest the
    /// keys: Up from the message box goes to it, where a question's rows
    /// stand over the box and Up goes to the last.
    fn in_a_row(&self) -> bool {
        matches!(self.target, AskAnswer::Approval { .. })
    }
}

fn question_from_event(body: &Value) -> Option<OpenQuestion> {
    if body.get("waiting").and_then(Value::as_bool) != Some(true) {
        return None;
    }
    let chat_id = body.get("chat")?.as_str()?.to_owned();
    let options = body
        .get("options")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .filter_map(|option| {
            let option = option.trim();
            (!option.is_empty()).then(|| option.chars().take(1_000).collect())
        })
        .take(6)
        .collect::<Vec<String>>();
    let accepts_input = body
        .get("accepts_input")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if options.len() < 2 && !accepts_input {
        return None;
    }
    let question = body
        .get("question")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|question| !question.is_empty())
        .unwrap_or("Which one?")
        .chars()
        .take(2_000)
        .collect();
    Some(OpenQuestion {
        chat_id,
        question,
        options,
        accepts_input,
    })
}

fn connection_state_key(endpoint: ChatEndpoint, remote: Option<&str>) -> String {
    match endpoint {
        ChatEndpoint::Local => "local".into(),
        ChatEndpoint::Remote => {
            format!("remote/{}", remote.unwrap_or("ssh"))
        }
    }
}

fn global_terminal_panel_id(connection_key: &str) -> String {
    format!("global:{connection_key}")
}

fn update_terminal_activity_state(
    activity: &mut HashMap<(ChatEndpoint, String, String), bool>,
    endpoint: ChatEndpoint,
    chat_id: &str,
    terminal_id: &str,
    working: Option<bool>,
) -> bool {
    let key = (endpoint, chat_id.to_owned(), terminal_id.to_owned());
    if let Some(working) = working {
        activity.insert(key, working);
    } else {
        activity.remove(&key);
    }
    activity
        .iter()
        .any(|((candidate_endpoint, candidate_chat, _), working)| {
            *candidate_endpoint == endpoint && candidate_chat == chat_id && *working
        })
}

fn terminal_panel_cache_entry_is_live(chat_id: &str, live_chats: &HashSet<String>) -> bool {
    chat_id.starts_with("global:") || live_chats.contains(chat_id)
}

/// Plain tool calls in a row read as one work log, showing its newest steps.
const WORK_LOG_VISIBLE: usize = 6;

/// Where a row sits inside a run of consecutive plain activity, so the run reads
/// as one card instead of one card per command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct WorkRun {
    start: usize,
    len: usize,
    position: usize,
    /// Entries the log lists once identical neighbours merge, and which of
    /// them this row belongs to.
    entries: usize,
    entry: usize,
    /// Where this row's identical neighbours begin, and how many there are,
    /// counting this row.
    repeat_start: usize,
    repeats: usize,
}

impl WorkRun {
    /// The newest of identical neighbours draws their entry, so the run's last
    /// row always has one to close the frame around.
    fn draws_entry(self) -> bool {
        self.start + self.position + 1 == self.repeat_start + self.repeats
    }

    /// Entries the collapsed log leaves out: everything but the newest.
    fn entry_is_collapsed(self, expanded: bool) -> bool {
        !expanded && self.entry + WORK_LOG_VISIBLE < self.entries
    }

    /// Rows that draw nothing. The head row stays to carry the log's header.
    fn hides(self, expanded: bool) -> bool {
        self.position > 0 && !self.shows_entry(expanded)
    }

    fn shows_entry(self, expanded: bool) -> bool {
        self.draws_entry() && !self.entry_is_collapsed(expanded)
    }

    fn hidden_count(self, expanded: bool) -> usize {
        if expanded {
            0
        } else {
            self.entries.saturating_sub(WORK_LOG_VISIBLE)
        }
    }
}

/// Live replies up to this size are formatted on every flush.
const LIVE_MARKDOWN_BYTES: usize = 48 * 1024;

/// A delegated agent still at work.
#[derive(Clone)]
struct RunningAgent {
    view: SubagentView,
}

/// A chat this chat's agent started with xd's start_agent tool that is at
/// work or waiting on the user, as the tree has it now.
#[derive(Clone, Debug, PartialEq, Eq)]
struct TrayWorker {
    chat: String,
    title: String,
    /// The assistant it runs on, as the tree names it.
    backend: String,
    needs_you: bool,
}

/// Where an image in the transcript has got to.
#[derive(Clone)]
enum MessageImageState {
    Loading,
    Ready(ReadyImage),
    Unavailable,
}

#[derive(Clone)]
struct ReadyImage {
    image: MessageImage,
    /// The frame that last drew it, so the images kept are the ones in use.
    drawn: Rc<Cell<u64>>,
}

type MessageImages = HashMap<String, MessageImageState>;

/// The tallest an image is drawn in a transcript, so a long screenshot cannot
/// push the rest of the turn out of view.
const MESSAGE_IMAGE_MAX_HEIGHT: f32 = 480.0;
/// What the image viewer leaves around an image, showing the window it is over.
const IMAGE_VIEWER_MARGIN: f32 = 32.0;
/// Past this a column stops narrowing and its table scrolls sideways instead.
const TABLE_COLUMN_MIN_WIDTH: f32 = 88.0;

/// How much memory images in a chat may hold. Scrolling through a long chat
/// should not keep every image it passes.
const MESSAGE_IMAGE_BUDGET: usize = 256 * 1024 * 1024;
/// The most images the host lets one reply show. All of a row's images count as
/// drawn together, so a full row has to fit the budget for scrolling away from
/// anything else to be enough to get back under it.
const MAX_IMAGES_IN_A_ROW: usize = 32;
const _: () = assert!(MAX_IMAGES_IN_A_ROW * MAX_MESSAGE_IMAGE_BYTES <= MESSAGE_IMAGE_BUDGET);

/// Which images to let go of to get back under budget: the longest undrawn first,
/// and never one the latest frame drew, which would only be asked for again. Each
/// image is `(path, bytes, last drawn frame)`.
fn images_over_budget(
    mut images: Vec<(String, usize, u64)>,
    budget: usize,
    frame: u64,
) -> Vec<String> {
    let mut total = images.iter().map(|(_, bytes, _)| bytes).sum::<usize>();
    images.sort_by_key(|(_, _, drawn)| *drawn);
    let mut evicted = Vec::new();
    for (path, bytes, drawn) in images {
        if total <= budget || drawn >= frame {
            break;
        }
        total -= bytes;
        evicted.push(path);
    }
    evicted
}

#[derive(Clone, Default)]
struct TranscriptSnapshot {
    messages: Arc<Vec<Message>>,
    live_text: Option<Arc<Message>>,
    live_items: Arc<Vec<Message>>,
    /// Agents still running, kept with the rows so a frame need not parse
    /// every record to find them.
    running_agents: Arc<Vec<RunningAgent>>,
    /// Each row's place in its work log, kept with the rows so measuring a long
    /// log need not compare its text again for every row.
    work_runs: Arc<Vec<Option<WorkRun>>>,
    /// For each row the user sent in reply to a tagged question, that
    /// question, so the bubble can say what it answers.
    answered_questions: Arc<Vec<Option<String>>>,
}

impl TranscriptSnapshot {
    fn sync_messages(&mut self, model: &AppModel) {
        self.messages = Arc::new(model.messages.clone());
        self.sync_derived_rows();
    }

    /// Rows the list draws. The list's item count must always equal this,
    /// so every change to the count is computed from the snapshot, never from
    /// the model, which can run ahead of it (live text waits for its frame).
    fn len(&self) -> usize {
        self.messages.len() + self.live_items.len() + usize::from(self.live_text.is_some())
    }

    /// Replaces a record's row with its newest snapshot, found by message id.
    /// The row count never changes.
    fn replace_record(&mut self, id: i64, text: &str) -> Option<usize> {
        let message = Message::new(Some(id), "tool", text, None);
        let row = if let Some(index) = self.messages.iter().position(|row| row.id == Some(id)) {
            Arc::make_mut(&mut self.messages)[index] = message;
            index
        } else {
            let index = self.live_items.iter().position(|row| row.id == Some(id))?;
            Arc::make_mut(&mut self.live_items)[index] = message;
            self.messages.len() + index
        };
        self.sync_derived_rows();
        Some(row)
    }

    fn sync_derived_rows(&mut self) {
        self.sync_running_agents();
        self.sync_work_runs();
        self.sync_answered_questions();
    }

    /// A user row answers the question a reply asked when that reply is the
    /// row before it, as `sync_question_from_history` reads a waiting one.
    ///
    /// Only a reply with a message right after it is parsed, so a live update
    /// does not read every reply in a long chat again.
    fn sync_answered_questions(&mut self) {
        let mut reply: Option<&Message> = None;
        self.answered_questions = Arc::new(
            self.messages
                .iter()
                .chain(self.live_items.iter())
                .map(|message| match message.role.as_str() {
                    // The turn's duration sits between a reply and the answer.
                    "duration" => None,
                    "user" => reply
                        .take()
                        .and_then(|reply| markdown::ask(&reply.content))
                        .map(|ask| ask.question),
                    "assistant" => {
                        reply = Some(message);
                        None
                    }
                    _ => {
                        reply = None;
                        None
                    }
                })
                .collect(),
        );
    }

    fn answered_question(&self, index: usize) -> Option<&str> {
        self.answered_questions.get(index)?.as_deref()
    }

    fn sync_running_agents(&mut self) {
        let rows = self.messages.iter().chain(self.live_items.iter());
        self.running_agents = Arc::new(
            rows.filter(|message| message.role == "tool")
                .filter_map(|message| match message.tool_view() {
                    // An agent chat has its own chat to open, not a tab here.
                    Some(ToolView::Subagent(view))
                        if view.status == SubagentState::Running && view.chat.is_empty() =>
                    {
                        Some(RunningAgent { view: view.clone() })
                    }
                    _ => None,
                })
                .collect(),
        );
    }

    fn sync_live_text(&mut self, model: &AppModel) {
        // Formatted while it streams, so closing the text does not reflow it.
        // A very long reply streams as plain text to keep each flush cheap.
        self.live_text = (!model.live_text.is_empty()).then(|| {
            let label = model.live_label();
            Arc::new(if model.live_text.len() <= LIVE_MARKDOWN_BYTES {
                Message::new_streaming(None, "assistant", model.live_text.clone(), label)
            } else {
                Message::new_plain(None, "assistant", model.live_text.clone(), label)
            })
        });
    }

    fn sync_live_items(&mut self, model: &AppModel) {
        // Each tool event adds a row at the end of a turn that can already
        // hold hundreds: copy only the rows that changed.
        let kept = self
            .live_items
            .iter()
            .zip(&model.live_items)
            .take_while(|(shown, current)| shown.same_row(current))
            .count();
        if kept != self.live_items.len() || kept != model.live_items.len() {
            let items = Arc::make_mut(&mut self.live_items);
            items.truncate(kept);
            items.extend(model.live_items[kept..].iter().cloned());
        }
        self.sync_derived_rows();
    }

    fn sync_work_runs(&mut self) {
        let rows = self
            .messages
            .iter()
            .chain(self.live_items.iter())
            .collect::<Vec<_>>();
        let stacks = |message: &Message| {
            message.role == "tool" && activity::is_plain_activity(&message.content)
        };
        let mut runs = vec![None; rows.len()];
        let mut start = 0;
        while start < rows.len() {
            let mut end = start;
            while end < rows.len() && stacks(rows[end]) {
                end += 1;
            }
            if end - start > 1 {
                // The whole text must match: rows that only look alike, such as
                // long commands sharing a truncated start, open onto different
                // details.
                let entry_starts = (start..end)
                    .filter(|&row| row == start || rows[row].content != rows[row - 1].content)
                    .collect::<Vec<_>>();
                for (entry, &repeat_start) in entry_starts.iter().enumerate() {
                    let repeat_end = entry_starts.get(entry + 1).copied().unwrap_or(end);
                    let repeats = &mut runs[repeat_start..repeat_end];
                    for (offset, run) in repeats.iter_mut().enumerate() {
                        *run = Some(WorkRun {
                            start,
                            len: end - start,
                            position: repeat_start + offset - start,
                            entries: entry_starts.len(),
                            entry,
                            repeat_start,
                            repeats: repeat_end - repeat_start,
                        });
                    }
                }
            }
            start = end.max(start + 1);
        }
        self.work_runs = Arc::new(runs);
    }

    /// The run of plain activity a row belongs to, when there is more than one.
    fn work_run(&self, index: usize) -> Option<WorkRun> {
        self.work_runs.get(index).copied().flatten()
    }

    fn row_key(&self, index: usize) -> i64 {
        self.get(index)
            .and_then(|message| message.id)
            .unwrap_or(-(index as i64) - 1)
    }

    fn get(&self, index: usize) -> Option<&Message> {
        if let Some(message) = self.messages.get(index) {
            return Some(message);
        }
        let mut live_index = index.saturating_sub(self.messages.len());
        if let Some(item) = self.live_items.get(live_index) {
            return Some(item);
        }
        live_index = live_index.saturating_sub(self.live_items.len());
        if let Some(live_text) = self.live_text.as_deref()
            && live_index == 0
        {
            return Some(live_text);
        }
        None
    }
}

