    #[gpui::test]
    fn a_running_compaction_asks_the_pulse_to_redraw_the_window(cx: &mut gpui::TestAppContext) {
        // The divider breathes with the shared pulse: drawing it while it
        // runs notes the frame as animated, so each pulse step redraws the
        // window, and a finished one asks for nothing.
        install_embedded_fonts(cx.text_system()).unwrap();
        set_reduce_motion(false);
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        let show = |state: &str, desktop: &mut XdDesktop| {
            desktop.transcript_snapshot.messages = Arc::new(vec![
                Message::new(Some(1), "user", "Tidy the history", None),
                Message::new(
                    Some(2),
                    "tool",
                    &format!("context_compaction\n{state}\nCompacting context"),
                    None,
                ),
            ]);
            desktop.transcript_snapshot.sync_derived_rows();
            desktop.transcript_loaded = true;
            desktop.transcript_loading = false;
            desktop.sync_transcript_count(true);
        };
        desktop.update(cx, |desktop, _| {
            desktop.model = grouped_workspace_fixture();
            desktop.model.select_chat("implementation");
            desktop.model.backend = "claude".into();
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "atlas".into(),
                chat_id: "implementation".into(),
                agent: AgentCli::Claude,
            };
            desktop.settings.browser_sessions.clear();
            show("completed", desktop);
        });
        cx.simulate_resize(size(px(1100.0), px(800.0)));
        cx.run_until_parked();
        redraw(cx);
        let finished = ANIMATION_DRAWN.with(Cell::get);
        desktop.update(cx, |desktop, cx| {
            show("running", desktop);
            cx.notify();
        });
        redraw(cx);
        assert!(
            ANIMATION_DRAWN.with(Cell::get),
            "a running compaction pulses"
        );
        assert!(!finished, "a finished compaction holds still");
    }

    #[gpui::test]
    fn dragging_across_a_code_block_selects_its_text(cx: &mut gpui::TestAppContext) {
        let code = "first line of code\nsecond line of code";
        let cx = table_transcript(cx, 1100.0, &format!("Run this:\n\n```sh\n{code}\n```"));
        let bounds = cx.debug_bounds("native-code").unwrap();
        // Inside the block's padding: from the start of the first line to the
        // middle of the second.
        let from = point(bounds.left() + px(14.0), bounds.top() + px(20.0));
        let to = point(bounds.left() + px(60.0), bounds.top() + px(40.0));
        cx.simulate_mouse_move(from, None, gpui::Modifiers::default());
        cx.simulate_mouse_down(from, MouseButton::Left, gpui::Modifiers::default());
        cx.simulate_mouse_move(to, Some(MouseButton::Left), gpui::Modifiers::default());
        cx.simulate_mouse_up(to, MouseButton::Left, gpui::Modifiers::default());
        cx.run_until_parked();

        let selected = cx.update(|_, cx| TextSelection::selected(cx)).unwrap();
        assert!(
            selected.starts_with("first line of code\nsec"),
            "{selected:?}"
        );
        assert!(code.starts_with(&selected), "{selected:?}");
    }

    #[gpui::test]
    fn a_table_too_long_for_one_line_wraps_inside_aligned_columns(cx: &mut gpui::TestAppContext) {
        let prose = "A cell with far more to say than one line of the column can hold. ".repeat(3);
        let table = format!(
            "| Check | Result | Empty |\n|---|---|---|\n| Review | Clean | |\n| {prose} | {prose} | |"
        );
        let cx = table_transcript(cx, 1100.0, &table);

        let bounds = cx.debug_bounds("native-table").unwrap();
        for column in 0..3 {
            let header = cx
                .debug_bounds(format!("native-table-cell-0-{column}").leak())
                .unwrap();
            for row in 1..3 {
                let cell = cx
                    .debug_bounds(format!("native-table-cell-{row}-{column}").leak())
                    .unwrap();
                assert_eq!(cell.left(), header.left());
                assert_eq!(cell.size.width, header.size.width);
            }
        }
        let last = cx.debug_bounds("native-table-cell-2-2").unwrap();
        assert!(
            last.right() <= bounds.right(),
            "the table fits its reading column"
        );
        let short = cx.debug_bounds("native-table-cell-1-0").unwrap();
        let wrapped = cx.debug_bounds("native-table-cell-2-0").unwrap();
        assert!(
            wrapped.size.height > short.size.height,
            "a long cell wraps in place"
        );
    }

    #[gpui::test]
    fn a_table_with_too_many_columns_scrolls_instead_of_crushing_them(
        cx: &mut gpui::TestAppContext,
    ) {
        let row = |cell: &str| format!("|{}", format!(" {cell} |").repeat(14));
        let table = format!("{}\n{}\n{}", row("head"), row("---"), row("cell"));
        let cx = table_transcript(cx, 900.0, &table);

        let bounds = cx.debug_bounds("native-table").unwrap();
        let first = cx.debug_bounds("native-table-cell-1-0").unwrap();
        assert_eq!(first.size.width, px(TABLE_COLUMN_MIN_WIDTH));
        assert!(first.left() + px(TABLE_COLUMN_MIN_WIDTH * 14.0) > bounds.right());
    }

    #[gpui::test]
    fn compact_transcript_keeps_its_scroll_viewport_above_the_composer(
        cx: &mut gpui::TestAppContext,
    ) {
        install_embedded_fonts(cx.text_system()).unwrap();
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            desktop.model = grouped_workspace_fixture();
            desktop.model.select_chat("implementation");
            desktop.model.backend = "codex".into();
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "atlas".into(), chat_id: "implementation".into(), agent: AgentCli::Codex,
            };
            desktop.settings.browser_sessions.clear();
            desktop.transcript_snapshot.messages = Arc::new((0..12).map(|index| Message::new(
                Some(index), "assistant",
                format!("Message {index}. {}", "A paragraph that wraps at a narrow viewport and remains readable while scrolling. ".repeat(8)),
                None,
            )).collect());
            desktop.transcript_loaded = true;
            desktop.transcript_loading = false;
            desktop.sync_transcript_count(true);
        });
        cx.simulate_resize(size(px(760.0), px(560.0)));
        cx.run_until_parked();
        let composer = cx.debug_bounds("chat-composer").unwrap();
        desktop.update(cx, |desktop, _| {
            let viewport = desktop.transcript.viewport_bounds();
            assert!(viewport.size.height > px(0.0));
            assert!(
                viewport.bottom() <= composer.top(),
                "transcript must not paint under the composer"
            );
            assert!(
                desktop.transcript_pinned(),
                "the loaded transcript follows its newest message"
            );
            assert!(
                desktop.transcript.max_offset_for_scrollbar().height > px(0.0),
                "overflow remains scrollable"
            );
            desktop.transcript.scroll_to(ListOffset {
                item_ix: 0,
                offset_in_item: px(0.0),
            });
        });
        cx.update(|window, cx| {
            window.refresh();
            window.draw(cx).clear();
        });
        desktop.update(cx, |desktop, _| {
            let first = desktop
                .transcript
                .bounds_for_item(0)
                .expect("first message is reachable");
            assert!(first.top() >= desktop.transcript.viewport_bounds().top() - px(1.0));
        });
    }

