    #[test]
    fn records_replace_their_snapshot_row_without_changing_the_count() {
        let mut model = AppModel::default();
        model.messages = vec![
            Message::new(Some(1), "user", "go", None),
            Message::new(
                Some(2),
                "tool",
                "subagent_run\n{\"status\":\"running\"}",
                None,
            ),
        ];
        model.live_items = vec![Message::new(Some(5), "tool", "subagent_run\n{}", None)];
        let mut snapshot = TranscriptSnapshot::default();
        snapshot.sync_messages(&model);
        snapshot.sync_live_items(&model);
        assert_eq!(snapshot.len(), 3);
        assert_eq!(snapshot.running_agents.len(), 2);

        // The model may already have moved on (a reply cleared its live rows);
        // the snapshot keeps what the list draws until it is synced.
        model.live_items.clear();
        assert_eq!(
            snapshot.replace_record(5, "subagent_run\n{\"status\":\"completed\"}"),
            Some(2)
        );
        assert_eq!(
            snapshot.replace_record(2, "subagent_run\n{\"status\":\"stopped\"}"),
            Some(1)
        );
        assert_eq!(snapshot.len(), 3);
        assert!(snapshot.running_agents.is_empty());
        assert_eq!(snapshot.replace_record(99, "x"), None);
    }

    fn work_log(rows: &[&str]) -> TranscriptSnapshot {
        let mut model = AppModel::default();
        model.messages = rows
            .iter()
            .enumerate()
            .map(|(id, text)| Message::new(Some(id as i64), "tool", *text, None))
            .collect();
        let mut snapshot = TranscriptSnapshot::default();
        snapshot.sync_messages(&model);
        snapshot
    }

    #[test]
    fn a_message_sent_right_after_a_question_says_what_it_answers() {
        let mut model = AppModel::default();
        let ask = "Ready.\n\n<ask>\nWhich region?\n- us-east-1\n- eu-west-1\n</ask>";
        model.messages = vec![
            Message::new(Some(1), "user", "Deploy staging.", None),
            Message::new(Some(2), "assistant", ask, None),
            Message::new(Some(3), "duration", "4", None),
            Message::new(Some(4), "user", "eu-west-1", None),
            Message::new(Some(5), "assistant", "Done.", None),
            Message::new(Some(6), "user", "Thanks", None),
            // A question the agent moved past before anyone answered.
            Message::new(Some(7), "assistant", ask, None),
            Message::new(Some(8), "tool", "Read a", None),
            Message::new(Some(9), "user", "Unrelated", None),
        ];
        let mut snapshot = TranscriptSnapshot::default();
        snapshot.sync_messages(&model);
        let answered = (0..snapshot.len())
            .map(|index| snapshot.answered_question(index))
            .collect::<Vec<_>>();
        assert_eq!(
            answered,
            [
                None,
                None,
                None,
                Some("Which region?"),
                None,
                None,
                None,
                None,
                None
            ]
        );
        assert_eq!(
            answered_question_label("Which region?"),
            "Answering \u{201c}Which region?\u{201d}"
        );
    }

    /// The rows a work log draws an entry for, and the count each one shows.
    fn drawn_entries(log: &TranscriptSnapshot, expanded: bool) -> Vec<(usize, usize)> {
        (0..log.len())
            .filter_map(|index| Some((index, log.work_run(index)?)))
            .filter(|(_, run)| run.shows_entry(expanded))
            .map(|(index, run)| (index, run.repeats))
            .collect()
    }

    #[test]
    fn identical_neighbours_in_a_work_log_merge_into_one_counted_entry() {
        let log = work_log(&["Read a", "Read a", "Bash x", "Read a", "Read a", "Read a"]);
        assert_eq!(drawn_entries(&log, false), [(1, 2), (2, 1), (5, 3)]);
        // Only neighbours merge, so the later reads stay their own entry.
        let head = log.work_run(0).unwrap();
        assert_eq!((head.len, head.entries, head.repeat_start), (6, 3, 0));
        assert!(!head.hides(false));
        assert!(!head.shows_entry(false));
        assert!(log.work_run(3).unwrap().hides(true));
        assert!(log.work_run(4).unwrap().hides(true));
        // An open entry keeps its key as newer repeats take over drawing it.
        assert_eq!(log.work_run(5).unwrap().repeat_start, 3);

        // The header still counts every step, even with one entry left.
        let same = work_log(&["Read a", "Read a", "Read a"]);
        assert_eq!(drawn_entries(&same, false), [(2, 3)]);
        assert_eq!(same.work_run(2).unwrap().len, 3);
        assert_eq!(same.work_run(0).unwrap().hidden_count(false), 0);
    }

    #[test]
    fn work_log_follows_live_rows_and_breaks_at_other_rows() {
        let mut model = AppModel::default();
        model.messages = vec![
            Message::new(Some(1), "tool", "Read a", None),
            Message::new(Some(2), "tool", "Read a", None),
            Message::new(Some(3), "assistant", "Read a", None),
            Message::new(Some(4), "tool", "Read a", None),
        ];
        let mut snapshot = TranscriptSnapshot::default();
        snapshot.sync_messages(&model);
        assert_eq!(snapshot.work_run(1).map(|run| run.repeats), Some(2));
        assert_eq!(snapshot.work_run(2), None);
        // A lone row is not a log until another joins it.
        assert_eq!(snapshot.work_run(3), None);

        // A live row joins the stored run before it, across the seam.
        model.live_items = vec![Message::new(None, "tool", "Read a", None)];
        snapshot.sync_live_items(&model);
        let tail = snapshot.work_run(4).unwrap();
        assert_eq!((tail.start, tail.repeat_start, tail.repeats), (3, 3, 2));
        assert!(!snapshot.work_run(3).unwrap().hides(false));
        assert!(!snapshot.work_run(3).unwrap().shows_entry(false));
        assert_eq!(snapshot.work_run(5), None);

        // Clearing the live rows takes their place in the log with them.
        model.live_items.clear();
        snapshot.sync_live_items(&model);
        assert_eq!(snapshot.work_run(3), None);
        assert_eq!(snapshot.work_run(4), None);
    }

    #[test]
    fn work_log_rows_that_only_look_alike_stay_apart() {
        let long = "x".repeat(400);
        let first = format!("{long} one");
        let second = format!("{long} two");
        let log = work_log(&[&first, &second, "Error", "Error", "Done"]);
        let name = |row: usize| match log.get(row).and_then(Message::tool_view) {
            Some(ToolView::Activity(card)) => card.name.clone(),
            _ => panic!("row {row} is not an activity"),
        };
        assert_eq!(name(0), name(1));
        assert_eq!(drawn_entries(&log, false), [(0, 1), (1, 1), (3, 2), (4, 1)]);
    }

    #[test]
    fn collapsed_work_log_keeps_its_newest_entries_rather_than_rows() {
        let log = work_log(&[
            "Bash one",
            "Bash two",
            "Read remote",
            "Read docs",
            "Read main",
            "Read main",
            "Read settings",
            "Bash three",
            "Read main",
            "Read main",
            "Read main",
            "Read main",
            "Read main",
            "Read main",
        ]);
        let head = log.work_run(0).unwrap();
        assert_eq!((head.len, head.entries), (14, 8));
        assert_eq!(head.hidden_count(false), 2);
        assert_eq!(head.hidden_count(true), 0);
        assert_eq!(
            drawn_entries(&log, false),
            [(2, 1), (3, 1), (5, 2), (6, 1), (7, 1), (13, 6)]
        );
        assert_eq!(
            drawn_entries(&log, true),
            [
                (0, 1),
                (1, 1),
                (2, 1),
                (3, 1),
                (5, 2),
                (6, 1),
                (7, 1),
                (13, 6)
            ]
        );
        // The head row stays for the header, and the tail closes the frame.
        assert!(!head.hides(false));
        assert!(log.work_run(1).unwrap().hides(false));
        assert!(!log.work_run(13).unwrap().hides(false));

        // Six entries fit without a toggle, however many steps they hold.
        let fits = work_log(&["a", "a", "a", "b", "c", "d", "e", "f", "f"]);
        let head = fits.work_run(0).unwrap();
        assert_eq!((head.len, head.entries), (9, 6));
        assert_eq!(head.hidden_count(false), 0);
    }

