    /// What a key does in a context, by the name of the action it reaches.
    fn key_action(keymap: &gpui::Keymap, key: &str, contexts: &[&str]) -> Option<String> {
        let contexts = contexts
            .iter()
            .map(|context| gpui::KeyContext::parse(context).unwrap())
            .collect::<Vec<_>>();
        let keystroke = gpui::Keystroke::parse(key).unwrap();
        keymap
            .bindings_for_input(&[keystroke], &contexts)
            .0
            .first()
            .map(|binding| binding.action().name().to_owned())
    }

    #[test]
    fn the_windows_shortcuts_leave_the_terminal_and_text_boxes_their_keys() {
        let mut before = base_key_bindings();
        before.extend(undo_key_bindings());
        let before = gpui::Keymap::new(before);
        let after = gpui::Keymap::new(all_key_bindings());
        let mut keys = vec![
            "ctrl-t",
            "cmd-t",
            "ctrl-w",
            "cmd-w",
            "ctrl-tab",
            "ctrl-shift-tab",
            "alt-down",
            "alt-up",
            "alt-shift-down",
            "ctrl-.",
            "cmd-.",
            "ctrl-shift-backspace",
            "cmd-shift-backspace",
            "ctrl-b",
            "cmd-b",
            "ctrl-`",
            "ctrl-,",
            "cmd-,",
            "ctrl-l",
            "cmd-l",
            "shift-escape",
            "f6",
            "shift-f6",
            "ctrl-k",
            "cmd-k",
            "ctrl-shift-t",
            "cmd-shift-t",
            "ctrl-=",
            "cmd-=",
            "ctrl--",
            "cmd--",
            "ctrl-0",
            "cmd-0",
            "up",
            "down",
            "enter",
            "tab",
            "shift-tab",
            "shift-f10",
            "menu",
            "pageup",
            "pagedown",
            "ctrl-home",
            "ctrl-end",
            "ctrl-z",
            "cmd-z",
            "ctrl-alt-left",
            "cmd-alt-left",
            "ctrl-alt-right",
            "cmd-alt-right",
            "ctrl-alt-shift-left",
            "cmd-alt-shift-left",
            "ctrl-alt-shift-right",
            "cmd-alt-shift-right",
            "ctrl-alt-up",
            "cmd-alt-up",
            "ctrl-alt-down",
            "cmd-alt-down",
        ];
        if cfg!(target_os = "macos") {
            keys.extend(["cmd-up", "cmd-down"]);
        }
        // Space, the arrows across, Home and End work only while the Tab
        // ring is on a control, which has the keyboard then.
        let ring_keys = [
            ("space", "xd::KeyPress"),
            ("left", "xd::KeyLeft"),
            ("right", "xd::KeyRight"),
            ("home", "xd::KeyHome"),
            ("end", "xd::KeyEnd"),
        ];
        // Alt+Shift+Up and Down move the tree row the ring is on, and are
        // the window's keys everywhere else.
        let ring_moves = [
            ("alt-shift-up", "xd::MoveRowUp"),
            ("alt-shift-down", "xd::MoveRowDown"),
        ];
        assert_eq!(
            keys.len() + ring_keys.len() + ring_moves.len(),
            app_key_bindings().len(),
            "every shortcut of the window is checked here"
        );
        let unmoved = gpui::Keymap::new(
            all_key_bindings()
                .into_iter()
                .filter(|binding| !binding.action().name().starts_with("xd::MoveRow"))
                .collect(),
        );
        for (key, action) in ring_moves {
            assert_eq!(
                key_action(&after, key, &["XdDesktop", KEY_STOP_CONTEXT]).as_deref(),
                Some(action)
            );
            for context in [
                vec!["XdDesktop"],
                vec!["XdDesktop", "TerminalInput"],
                vec!["XdDesktop", "ComposerInput"],
                vec!["XdDesktop", "FileEditor"],
                vec!["XdDesktop", "MessageEditor"],
            ] {
                assert_eq!(
                    key_action(&after, key, &context),
                    key_action(&unmoved, key, &context),
                    "{key} in {context:?}"
                );
            }
        }
        // Off a tree row, the ring's Alt+Shift+Down goes on to the next
        // session waiting on you.
        let keystroke = gpui::Keystroke::parse("alt-shift-down").unwrap();
        let ringed = [
            gpui::KeyContext::parse("XdDesktop").unwrap(),
            gpui::KeyContext::parse(KEY_STOP_CONTEXT).unwrap(),
        ];
        let reached = after
            .bindings_for_input(&[keystroke], &ringed)
            .0
            .iter()
            .map(|binding| binding.action().name().to_owned())
            .collect::<Vec<_>>();
        assert_eq!(reached, ["xd::MoveRowDown", "xd::NextWaitingSession"]);
        for (key, action) in ring_keys {
            assert_eq!(
                key_action(&after, key, &["XdDesktop", KEY_STOP_CONTEXT]).as_deref(),
                Some(action)
            );
            // A text box and the terminal never lose them.
            for context in [
                vec!["XdDesktop"],
                vec!["XdDesktop", "TerminalInput"],
                vec!["XdDesktop", "ComposerInput"],
                vec!["XdDesktop", "FileEditor"],
                vec!["XdDesktop", "MessageEditor"],
            ] {
                assert_eq!(
                    key_action(&after, key, &context),
                    key_action(&before, key, &context),
                    "{key} in {context:?}"
                );
            }
        }
        for key in keys.iter().copied() {
            // Alone in the window, the key is the window's.
            let window = key_action(&after, key, &["XdDesktop"]).unwrap();
            assert!(window.starts_with("xd::"), "{key} reaches {window}");
            for inner in [
                "TerminalInput",
                "ComposerInput",
                "FileEditor",
                "MessageEditor",
            ] {
                let contexts = ["XdDesktop", inner];
                let was = key_action(&before, key, &contexts);
                let is = key_action(&after, key, &contexts);
                match was {
                    // A key the box or the terminal had keeps doing what it did.
                    Some(was) => assert_eq!(is.as_deref(), Some(was.as_str()), "{key} in {inner}"),
                    // A key it never had is the window's there too.
                    None => assert_eq!(is.as_deref(), Some(window.as_str()), "{key} in {inner}"),
                }
            }
        }
        // The terminal keeps every Ctrl and letter it sends to the shell.
        for (key, action) in [
            ("ctrl-t", "ControlT"),
            // A shell deletes the word before the cursor.
            ("ctrl-w", "ControlW"),
            ("ctrl-b", "ControlB"),
            ("ctrl-l", "ClearScreen"),
            ("ctrl-k", "ControlK"),
            ("ctrl-z", "Suspend"),
            ("up", "Up"),
            ("tab", "Tab"),
            ("enter", "Submit"),
            ("pageup", "PageUp"),
            // Programs read Alt with an arrow; the window steps sessions
            // with these only outside the terminal.
            ("alt-up", "AltUp"),
            ("alt-down", "AltDown"),
            ("alt-shift-down", "AltShiftDown"),
        ] {
            let is = key_action(&after, key, &["XdDesktop", "TerminalInput"]).unwrap();
            assert!(
                is.ends_with(action) && !is.starts_with("xd::"),
                "{key} in the terminal reaches {is}"
            );
        }
        // And these reach the window from the terminal, which has no use for them.
        for key in [
            "ctrl-tab",
            "ctrl-.",
            "ctrl-shift-backspace",
            "ctrl-`",
            "ctrl-,",
            "ctrl-shift-t",
            "shift-escape",
            "f6",
            "shift-f6",
            "ctrl-=",
            "ctrl--",
            "ctrl-0",
        ] {
            let is = key_action(&after, key, &["XdDesktop", "TerminalInput"]).unwrap();
            assert!(is.starts_with("xd::"), "{key} in the terminal reaches {is}");
        }
        // The keys that always leave the terminal, and the second Stop key,
        // reach the same action from every text box as well.
        for (key, action) in [
            ("shift-escape", "xd::LeaveToMessageBox"),
            ("f6", "xd::NextRegion"),
            ("shift-f6", "xd::PreviousRegion"),
            ("ctrl-shift-backspace", "xd::StopTurn"),
        ] {
            for inner in [
                "TerminalInput",
                "ComposerInput",
                "FileEditor",
                "MessageEditor",
                KEY_STOP_CONTEXT,
            ] {
                assert_eq!(
                    key_action(&after, key, &["XdDesktop", inner]).as_deref(),
                    Some(action),
                    "{key} in {inner}"
                );
            }
        }
    }

    /// Which of the Tab stops the keyboard is on: the control the ring is
    /// on, or the field that has the keyboard, as `fields` names them. Unix
    /// only, like the tests that use it.
    #[cfg(unix)]
    fn keyboard_at(
        desktop: &Entity<XdDesktop>,
        cx: &mut gpui::VisualTestContext,
        fields: &[(&str, FocusHandle)],
    ) -> String {
        if let Some(on) = ring(desktop, cx) {
            return on;
        }
        cx.update_window_entity(desktop, |_, window, _| {
            fields
                .iter()
                .find(|(_, focus)| focus.is_focused(window))
                .map_or_else(String::new, |(name, _)| (*name).to_owned())
        })
    }

    #[cfg(unix)]
    #[gpui::test]
    fn a_quota_stop_is_cleared_from_the_keyboard(cx: &mut gpui::TestAppContext) {
        cx.update(|cx| cx.bind_keys(all_key_bindings()));
        let (desktop, cx, mut requests, _updates) = docked_ask_fixture(cx);
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.model.chat_quotas_supported = true;
            desktop.model.quota = Some(ChatQuota {
                percent: 10,
                used: 10.4,
                own: false,
            });
            desktop.model.quota_reached = true;
            desktop.sync_quota_input(cx);
            // The message box had the keyboard, with nothing typed in it.
            window.focus(&desktop.composer_input.read(cx).focus_handle(cx));
        });
        redraw(cx);
        let fields = desktop.read_with(cx, |desktop, cx| {
            [
                ("quota", desktop.quota_input.read(cx).focus_handle(cx)),
                ("composer", desktop.composer_input.read(cx).focus_handle(cx)),
            ]
        });
        // The card takes the keyboard as it docks, in its New quota field.
        assert_eq!(keyboard_at(&desktop, cx, &fields), "quota");
        // Enter there is Continue, with the quota it holds.
        cx.simulate_keystrokes("enter");
        let request = next_request_with_op(&mut requests, "set-chat-quota");
        assert_eq!(request["percent"], 20);
        desktop.update(cx, |desktop, cx| {
            desktop.quota_card.pending = None;
            cx.notify();
        });
        redraw(cx);
        // Tab goes on to Continue and Continue without a limit, then the
        // message box; Enter presses the button the ring is on.
        cx.simulate_keystrokes("tab");
        redraw(cx);
        assert_eq!(keyboard_at(&desktop, cx, &fields), "chat-quota-continue");
        cx.simulate_keystrokes("tab");
        redraw(cx);
        assert_eq!(keyboard_at(&desktop, cx, &fields), "chat-quota-lift");
        cx.simulate_keystrokes("enter");
        let request = next_request_with_op(&mut requests, "set-chat-quota");
        assert!(request["percent"].is_null());
        desktop.update(cx, |desktop, cx| {
            desktop.quota_card.pending = None;
            cx.notify();
        });
        redraw(cx);
        // Space presses it too.
        for _ in 0..20 {
            if keyboard_at(&desktop, cx, &fields) == "chat-quota-continue" {
                break;
            }
            cx.simulate_keystrokes("tab");
            redraw(cx);
        }
        assert_eq!(keyboard_at(&desktop, cx, &fields), "chat-quota-continue");
        cx.simulate_keystrokes("space");
        assert_eq!(
            next_request_with_op(&mut requests, "set-chat-quota")["percent"],
            20
        );
    }

