    #[cfg(unix)]
    #[gpui::test]
    fn a_removed_queued_message_comes_back_where_it_stood(cx: &mut gpui::TestAppContext) {
        let (desktop, cx, mut requests, _updates) = docked_ask_fixture(cx);
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop.model.start_working();
            desktop.model.queue = vec!["first".into(), "second".into(), "third".into()];
            desktop.drop_queued(1, cx);
            assert_eq!(desktop.model.queue, ["first", "third"]);
            assert_eq!(desktop.undo_notice().as_deref(), Some("Removed"));
        });
        assert_eq!(
            next_request_with_op(&mut requests, "drop-queue")["index"],
            1
        );
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop.undo_last(cx);
            assert_eq!(desktop.model.queue, ["first", "second", "third"]);
            assert_eq!(desktop.undo_notice(), None);
        });
        assert_eq!(
            next_request_with_op(&mut requests, "queue")["text"],
            "second"
        );
        let reorder = next_request_with_op(&mut requests, "reorder-queue");
        assert_eq!(
            (reorder["source"].as_u64(), reorder["anchor"].as_u64()),
            (Some(2), Some(1))
        );
        assert_eq!(reorder["anchor-text"], "third");
        assert_eq!(reorder["after"], false);

        // Once the turn has ended there is no queue to return it to: it goes
        // back to the message box instead.
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop.drop_queued(0, cx);
            desktop.model.stop_working();
            desktop.undo_last(cx);
            assert_eq!(desktop.composer, "first");
        });
    }

    #[gpui::test]
    fn a_discarded_draft_comes_back_with_undo(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = keyboard_window(cx);
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.begin_chat_create("atlas".into(), window, cx);
            desktop
                .new_chat_input
                .update(cx, |input, cx| input.set_text("Port the palette", cx));
            desktop.new_chat_prompt = "Port the palette".into();
            desktop.persist_new_chat_draft();
            assert!(desktop.project_draft("atlas").is_some());

            desktop.discard_project_draft("atlas", cx);
            assert!(desktop.new_chat_prompt.is_empty());
            assert_eq!(desktop.undo_notice().as_deref(), Some("Discarded"));

            desktop.undo_last(cx);
            assert_eq!(desktop.new_chat_prompt, "Port the palette");
            assert_eq!(desktop.undo_notice(), None);
        });
        // A draft with nothing in it has nothing to bring back.
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop.discard_project_draft("atlas", cx);
            desktop.discard_project_draft("atlas", cx);
            assert_eq!(desktop.undo_notice().as_deref(), Some("Discarded"));
            desktop.undo_last(cx);
            desktop.discard_project_draft("website", cx);
            assert_eq!(desktop.undo_notice(), None);
        });
    }

    /// An open chat of sixty messages, far taller than the window, with
    /// xd's real keys.
    fn long_chat_window(
        cx: &mut gpui::TestAppContext,
    ) -> (Entity<XdDesktop>, &mut gpui::VisualTestContext) {
        install_embedded_fonts(cx.text_system()).unwrap();
        cx.update(|cx| cx.bind_keys(all_key_bindings()));
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            desktop.model = grouped_workspace_fixture();
            desktop.model.select_chat("implementation");
            desktop.model.backend = "codex".into();
            desktop.model.connected = true;
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "atlas".into(),
                chat_id: "implementation".into(),
                agent: AgentCli::Codex,
            };
            desktop.settings.browser_sessions.clear();
            desktop.transcript_snapshot.messages = Arc::new(
                (1..=60)
                    .map(|index| {
                        let role = if index % 2 == 0 { "user" } else { "assistant" };
                        let text = format!(
                            "Message {index}.\n\nA paragraph long enough to take a few lines of the \
                             column, so sixty of them make a chat much taller than the window."
                        );
                        Message::new(Some(index), role, &text, None)
                    })
                    .collect(),
            );
            desktop.transcript_snapshot.sync_derived_rows();
            desktop.transcript_loaded = true;
            desktop.transcript_loading = false;
            desktop.sync_transcript_count(true);
        });
        cx.simulate_resize(size(px(1100.0), px(700.0)));
        redraw(cx);
        (desktop, cx)
    }

    #[gpui::test]
    fn the_page_keys_scroll_the_transcript(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = long_chat_window(cx);
        let top = |desktop: &Entity<XdDesktop>, cx: &mut gpui::VisualTestContext| {
            desktop.read_with(cx, |desktop, _| {
                let top = desktop.transcript.logical_scroll_top();
                (top.item_ix, top.offset_in_item, desktop.transcript_pinned())
            })
        };
        assert!(top(&desktop, cx).2, "a chat opens on its newest message");
        cx.update_window_entity(&desktop, |desktop, window, _| {
            window.focus(&desktop.root_focus);
        });
        cx.simulate_keystrokes("pageup");
        redraw(cx);
        let (up, _, pinned) = top(&desktop, cx);
        assert!(!pinned, "Page Up leaves the bottom");
        cx.simulate_keystrokes("pageup");
        redraw(cx);
        assert!(top(&desktop, cx).0 < up, "and goes on up a page at a time");
        cx.simulate_keystrokes("ctrl-home");
        redraw(cx);
        assert_eq!(top(&desktop, cx), (0, px(0.0), false));
        cx.simulate_keystrokes("pagedown");
        redraw(cx);
        assert!(top(&desktop, cx).0 > 0 || top(&desktop, cx).1 > px(0.0));
        cx.simulate_keystrokes("ctrl-end");
        redraw(cx);
        assert!(top(&desktop, cx).2, "Ctrl+End follows the newest again");

        // The message box has no use for Page Up: from there it scrolls too.
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            window.focus(&desktop.composer_input.read(cx).focus_handle(cx));
        });
        cx.simulate_keystrokes("pageup");
        redraw(cx);
        assert!(!top(&desktop, cx).2);

        // A dialog over the chat takes nothing.
        cx.simulate_keystrokes("ctrl-end");
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.begin_workspace_create(window, cx);
        });
        redraw(cx);
        cx.simulate_keystrokes("pageup");
        redraw(cx);
        assert!(top(&desktop, cx).2);
    }

    #[gpui::test]
    fn the_page_keys_scroll_the_side_pane_once_it_is_clicked(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = long_chat_window(cx);
        let patch = (0..400)
            .map(|line| format!("+line {line}\n"))
            .collect::<String>();
        cx.update_window_entity(&desktop, |desktop, window, _| {
            desktop.diff_panel = Some(DiffPanel {
                patch: PatchView::new(&format!(
                    "diff --git a/a.rs b/a.rs\n--- a/a.rs\n+++ b/a.rs\n@@ -0,0 +1,400 @@\n{patch}"
                )),
                ..DiffPanel::default()
            });
            desktop.set_browser_open(true);
            desktop.native_pane = NativePane::Diff;
            window.focus(&desktop.root_focus);
        });
        redraw(cx);
        let diff = |desktop: &Entity<XdDesktop>, cx: &mut gpui::VisualTestContext| {
            desktop.read_with(cx, |desktop, _| {
                desktop.diff_scroll.0.borrow().base_handle.offset().y
            })
        };
        let pinned = |desktop: &Entity<XdDesktop>, cx: &mut gpui::VisualTestContext| {
            desktop.read_with(cx, |desktop, _| desktop.transcript_pinned())
        };
        // Until the side pane is pressed in, the keys stay with the chat.
        cx.simulate_keystrokes("pagedown");
        redraw(cx);
        assert_eq!(diff(&desktop, cx), px(0.0));
        let pane = cx.debug_bounds("native-side-pane").unwrap();
        cx.simulate_click(pane.center(), gpui::Modifiers::default());
        cx.update_window_entity(&desktop, |desktop, window, _| {
            window.focus(&desktop.root_focus);
        });
        cx.simulate_keystrokes("pagedown");
        redraw(cx);
        let down = diff(&desktop, cx);
        assert!(down < px(0.0), "the patch scrolls a page");
        assert!(pinned(&desktop, cx), "and the chat stays where it was");
        cx.simulate_keystrokes("ctrl-end");
        redraw(cx);
        assert!(diff(&desktop, cx) < down);
        cx.simulate_keystrokes("ctrl-home");
        redraw(cx);
        assert_eq!(diff(&desktop, cx), px(0.0));
        // A press in the chat gives the keys back to the transcript.
        let chat = cx.debug_bounds("chat-composer").unwrap();
        cx.simulate_click(
            point(chat.center().x, chat.top() - px(80.0)),
            gpui::Modifiers::default(),
        );
        cx.update_window_entity(&desktop, |desktop, window, _| {
            window.focus(&desktop.root_focus);
        });
        cx.simulate_keystrokes("pageup");
        redraw(cx);
        assert!(!pinned(&desktop, cx));
        assert_eq!(diff(&desktop, cx), px(0.0));
    }

    /// A small picture, as PNG bytes.
    fn tiny_png() -> Vec<u8> {
        let mut out = std::io::Cursor::new(Vec::new());
        image::RgbaImage::from_pixel(8, 8, image::Rgba([40, 80, 160, 255]))
            .write_to(&mut out, image::ImageFormat::Png)
            .unwrap();
        out.into_inner()
    }

    /// The names of the attachments in the open chat's draft.
    fn draft_names(desktop: &Entity<XdDesktop>, cx: &mut gpui::VisualTestContext) -> Vec<String> {
        desktop.read_with(cx, |desktop, _| {
            desktop
                .model
                .draft_attachments
                .iter()
                .map(|attachment| attachment.name.clone())
                .collect()
        })
    }

    #[gpui::test]
    fn a_drafts_attachments_open_and_go_from_the_keyboard(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = keyboard_window(cx);
        keyboard_chat(&desktop, cx);
        desktop.update(cx, |desktop, cx| {
            desktop.model.draft_attachments = vec![
                Attachment::from_png("palette.png", tiny_png()).unwrap(),
                Attachment::from_file("notes.txt", b"notes".to_vec()),
            ];
            cx.notify();
        });
        redraw(cx);
        // The picture is a Tab stop, named under the ring; Enter opens it in
        // the viewer, and Escape closes it.
        tab_to(&desktop, cx, "draft-image-0");
        assert!(named_under_ring(&desktop, cx));
        cx.simulate_keystrokes("enter");
        redraw(cx);
        desktop.read_with(cx, |desktop, _| assert!(desktop.image_preview.is_some()));
        cx.simulate_keystrokes("escape");
        redraw(cx);
        desktop.read_with(cx, |desktop, _| assert!(desktop.image_preview.is_none()));
        // Its Remove follows it, named for the file. Enter removes it, and
        // the undo notice puts it back where it stood.
        tab_to(&desktop, cx, "remove-draft-image-0");
        assert!(named_under_ring(&desktop, cx));
        cx.simulate_keystrokes("enter");
        redraw(cx);
        assert_eq!(draft_names(&desktop, cx), ["notes.txt"]);
        desktop.update(cx, |desktop, cx| {
            assert_eq!(desktop.undo_notice().as_deref(), Some("Removed"));
            desktop.undo_last(cx);
        });
        redraw(cx);
        assert_eq!(draft_names(&desktop, cx), ["palette.png", "notes.txt"]);
        // A file's Remove is a Tab stop too, after the pictures.
        let passed = tab_to(&desktop, cx, "remove-draft-file-0");
        assert!(named_under_ring(&desktop, cx));
        assert!(passed.iter().any(|on| on == "native-attach"), "{passed:?}");
        cx.simulate_keystrokes("space");
        redraw(cx);
        assert_eq!(draft_names(&desktop, cx), ["palette.png"]);
    }

    #[gpui::test]
    fn backspace_at_the_start_of_a_composer_removes_its_last_attachment(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx) = keyboard_window(cx);
        keyboard_chat(&desktop, cx);
        desktop.update(cx, |desktop, cx| {
            desktop.model.draft_attachments = vec![
                Attachment::from_file("notes.txt", b"notes".to_vec()),
                Attachment::from_png("palette.png", tiny_png()).unwrap(),
            ];
            cx.notify();
        });
        cx.simulate_keystrokes("ctrl-l");
        cx.simulate_input("ab");
        redraw(cx);
        // Text before the caret goes first, as ever.
        cx.simulate_keystrokes("backspace");
        redraw(cx);
        assert_eq!(draft_names(&desktop, cx).len(), 2);
        desktop.read_with(cx, |desktop, _| assert_eq!(desktop.composer, "a"));
        // At the very start, the last attachment shown goes: the file, which
        // follows the pictures. The text after the caret stays.
        cx.simulate_keystrokes("home backspace");
        redraw(cx);
        assert_eq!(draft_names(&desktop, cx), ["palette.png"]);
        desktop.update(cx, |desktop, cx| {
            assert_eq!(desktop.composer, "a");
            assert_eq!(desktop.undo_notice().as_deref(), Some("Removed"));
            desktop.undo_last(cx);
        });
        assert_eq!(draft_names(&desktop, cx), ["notes.txt", "palette.png"]);
        // The new chat's composer, empty, does the same. (With no host to
        // keep the chat's draft, the window would not leave the chat.)
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.draft_dirty = false;
            desktop.attachments_dirty = false;
            desktop.begin_chat_create("atlas".into(), window, cx);
            desktop.new_chat_attachments = vec![Attachment::from_file("plan.md", b"plan".to_vec())];
            desktop
                .new_chat_input
                .update(cx, |input, cx| input.set_text("", cx));
            window.focus(&desktop.new_chat_input.read(cx).focus_handle(cx));
        });
        redraw(cx);
        cx.simulate_keystrokes("backspace");
        redraw(cx);
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            let focused = desktop
                .new_chat_input
                .read(cx)
                .focus_handle(cx)
                .is_focused(window);
            assert!(
                desktop.new_chat_attachments.is_empty(),
                "focused {focused}, prompt {:?}, key {:?}, submitting {}",
                desktop.new_chat_prompt,
                desktop.new_chat_draft_key(),
                desktop.chat_create_submitting
            );
            assert_eq!(desktop.undo_notice().as_deref(), Some("Removed"));
            desktop.undo_last(cx);
            assert_eq!(desktop.new_chat_attachments.len(), 1);
        });
    }

