    #[gpui::test]
    fn opening_links_preserves_the_chats_open_tabs(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            desktop.active_endpoint = ChatEndpoint::Local;
            desktop.set_browser_open(false);
            desktop.settings.browser_sessions.clear();
            desktop.model.folders = vec![Folder {
                id: "link-project".into(),
                name: "Links".into(),
                parent: None,
                owner: None,
                group: false,
            }];
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "link-project".into(),
                chat_id: "link-chat".into(),
                agent: AgentCli::Codex,
            };
            cx.notify();
        });
        cx.run_until_parked();
        let target = cx.update(|window, _| window.window_handle());
        cx.dispatch_action(OpenBrowserUrl {
            url: "http://localhost:3000/first".into(),
            window: target,
        });
        let first = desktop.update(cx, |desktop, cx| {
            assert!(desktop.browser_is_open());
            let pane = desktop.browser_panes["local/chat/link-chat"].clone();
            assert_eq!(
                pane.read(cx).current_url().as_deref(),
                Some("http://localhost:3000/first")
            );
            pane
        });
        assert!(cx.opened_url().is_none());

        cx.dispatch_action(OpenBrowserUrl {
            url: "http://localhost:3000/second".into(),
            window: target,
        });
        desktop.update(cx, |desktop, cx| {
            let second = &desktop.browser_panes["local/chat/link-chat"];
            assert_eq!(first.entity_id(), second.entity_id());
            assert_eq!(
                second.read(cx).current_url().as_deref(),
                Some("http://localhost:3000/second")
            );
            assert_eq!(
                second.read(cx).session().tabs,
                vec![
                    Some("http://localhost:3000/first".into()),
                    Some("http://localhost:3000/second".into()),
                ]
            );
        });
        assert!(cx.opened_url().is_none());
    }

    /// Counts the times the desktop asks to be redrawn.
    fn count_redraws(
        desktop: &Entity<XdDesktop>,
        cx: &mut gpui::VisualTestContext,
    ) -> Rc<Cell<usize>> {
        let redraws = Rc::new(Cell::new(0));
        let counter = redraws.clone();
        cx.update(|_, cx| {
            cx.observe(desktop, move |_, _| counter.set(counter.get() + 1))
                .detach();
        });
        redraws
    }

    #[gpui::test]
    fn streamed_output_for_chats_off_screen_does_not_redraw(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            desktop.model = grouped_workspace_fixture();
            desktop.model.select_chat("implementation");
        });
        cx.run_until_parked();
        let redraws = count_redraws(&desktop, cx);
        desktop.update(cx, |desktop, cx| {
            let generation = desktop.connection_generation;
            for (name, body) in [
                (
                    "text",
                    serde_json::json!({"chat": "review", "text": "token"}),
                ),
                (
                    "tool",
                    serde_json::json!({"chat": "review", "text": "Ran ls"}),
                ),
                (
                    "record",
                    serde_json::json!({"chat": "review", "message_id": 4, "text": "x"}),
                ),
                (
                    "terminal-output",
                    serde_json::json!({"chat": "review", "terminal": "shell", "data": "aGk="}),
                ),
            ] {
                desktop.handle_host_update(
                    HostUpdate::Event {
                        name: name.into(),
                        body: body.as_object().unwrap().clone(),
                        attachments: None,
                    },
                    generation,
                    cx,
                );
            }
        });
        cx.run_until_parked();
        assert_eq!(redraws.get(), 0, "nothing on screen changed");

        // The shown chat's text waits for its live-text frame.
        desktop.update(cx, |desktop, cx| {
            desktop.handle_event(
                "text",
                serde_json::json!({"chat": "implementation", "text": "hello"}),
                None,
                cx,
            );
            desktop.handle_event(
                "text",
                serde_json::json!({"chat": "implementation", "text": " there"}),
                None,
                cx,
            );
        });
        cx.run_until_parked();
        assert_eq!(redraws.get(), 0);
        assert!(
            desktop.read_with(cx, |desktop, _| desktop.live_render_scheduled.is_some()),
            "its own frame redraws it"
        );

        // A change the sidebar shows still redraws.
        desktop.update(cx, |desktop, cx| {
            desktop.handle_event(
                "turn-started",
                serde_json::json!({"chat": "review"}),
                None,
                cx,
            );
        });
        cx.run_until_parked();
        assert!(redraws.get() > 0);
    }

    #[gpui::test]
    fn the_terminal_keeps_its_rendering_until_its_screen_changes(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            desktop.model.selected_chat = Some("dock-chat".into());
            desktop.show_native_pane(NativePane::Terminal, cx);
            let mut shell =
                XdDesktop::terminal_tab_from_snapshot(&serde_json::json!({"id": "shell"})).unwrap();
            // The cursor waits on the next line, so this one stays as it is.
            shell.screen.feed(b"first line https://example.com\r\n");
            let panel = desktop.terminal_panel.as_mut().unwrap();
            panel.loading = false;
            panel.sessions.push(shell);
            panel.selected = Some("shell".into());
        });
        cx.run_until_parked();
        let row = |desktop: &mut XdDesktop, index| {
            desktop.sync_terminal_rows();
            desktop.terminal_row(index).unwrap()
        };
        let first = desktop.update(cx, |desktop, _| row(desktop, 0));
        assert!(first.text.contains("first line"));
        assert_eq!(first.links.len(), 1, "found the link once");
        let again = desktop.update(cx, |desktop, _| row(desktop, 0));
        assert!(
            Rc::ptr_eq(&first, &again),
            "an unchanged screen is not rebuilt"
        );

        // Output for a terminal no frame drew changes nothing on screen.
        let redraws = count_redraws(&desktop, cx);
        let output = |text: &str| serde_json::json!({"chat": "dock-chat", "terminal": "shell", "data": STANDARD.encode(text)});
        desktop.update(cx, |desktop, cx| {
            desktop.terminal_drawn = false;
            desktop.handle_event("terminal-output", output("\nsecond"), None, cx);
        });
        cx.run_until_parked();
        assert_eq!(redraws.get(), 0);

        // Output for the drawn terminal redraws, with the new text.
        desktop.update(cx, |desktop, cx| {
            desktop.terminal_drawn = true;
            desktop.handle_event("terminal-output", output("\nthird"), None, cx);
        });
        cx.run_until_parked();
        assert!(redraws.get() > 0);
        // The line that did not change is kept; the new ones are built.
        let (kept, below) = desktop.update(cx, |desktop, _| {
            let below = (1..4)
                .map(|index| row(desktop, index).text.to_string())
                .collect::<Vec<_>>()
                .join("\n");
            (row(desktop, 0), below)
        });
        assert!(Rc::ptr_eq(&first, &kept));
        assert!(
            below.contains("second") && below.contains("third"),
            "{below:?}"
        );
    }

    #[gpui::test]
    fn switching_terminals_starts_their_rows_afresh(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            let mut panel = XdDesktop::new_terminal_panel("switch-test".into());
            panel.auto_open = false;
            panel.loading = false;
            for id in ["first", "second"] {
                let mut shell = XdDesktop::terminal_tab_from_snapshot(
                    &serde_json::json!({"id": id, "columns": 40, "rows": 4}),
                )
                .unwrap();
                shell.screen.feed(b"same line\r\n");
                panel.sessions.push(shell);
            }
            panel.selected = Some("first".into());
            desktop.terminal_panel = Some(panel);
            desktop.sync_terminal_rows();
            desktop.terminal_row(0);
            assert!(!desktop.terminal_rows.built.is_empty());
            // Another terminal's lines can hold the same text and still draw
            // differently, so none of the first one's rows are kept for it.
            desktop.terminal_panel.as_mut().unwrap().selected = Some("second".into());
            desktop.sync_terminal_rows();
            assert!(desktop.terminal_rows.built.is_empty());
        });
    }

    #[gpui::test]
    fn a_long_scrollback_builds_only_the_rows_in_view(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        cx.simulate_resize(size(px(1180.0), px(780.0)));
        desktop.update(cx, |desktop, cx| {
            let mut panel = XdDesktop::new_terminal_panel("scrollback-test".into());
            panel.auto_open = false;
            panel.loading = false;
            let mut shell = XdDesktop::terminal_tab_from_snapshot(
                &serde_json::json!({"id": "shell", "columns": 100, "rows": 30}),
            )
            .unwrap();
            let output = (1..=6000)
                .map(|line| format!("line {line}\r\n"))
                .collect::<String>();
            shell.screen.feed(output.as_bytes());
            panel.sessions.push(shell);
            panel.selected = Some("shell".into());
            desktop.terminal_panel = Some(panel);
            desktop.minimal_route = MinimalRoute::Terminal;
            desktop.terminal_scroll.scroll_to_bottom();
            cx.notify();
        });
        cx.run_until_parked();
        // Once the terminal has taken the window's size, a frame drawn from
        // nothing builds the rows it shows.
        redraw(cx);
        redraw(cx);
        let built = || TERMINAL_ROWS_BUILT.with(Cell::get);
        let before = built();
        desktop.update(cx, |desktop, cx| {
            desktop.terminal_rows.built.clear();
            cx.notify();
        });
        redraw(cx);
        // A full scrollback, of which only the rows in view, at its foot,
        // are built: some 40 of more than 5,000.
        let (count, newest) = desktop.read_with(cx, |desktop, _| {
            (
                desktop.terminal_rows.count,
                desktop
                    .terminal_rows
                    .built
                    .values()
                    .any(|row| row.text.as_ref() == "line 6000"),
            )
        });
        assert!(count > 5000, "{count}");
        let first = built() - before;
        assert!((20..=60).contains(&first), "built {first} rows of {count}");
        assert!(newest, "the newest line is in view");
        // At its foot, as before, the last line stands the output's padding
        // above the bottom edge.
        let output = cx.debug_bounds("minimal-terminal-output").unwrap();
        let last = cx
            .debug_bounds(Box::leak(
                format!("terminal-row-{}", count - 1).into_boxed_str(),
            ))
            .unwrap();
        let below = f32::from(output.bottom() - last.bottom());
        assert!(
            (below - TERMINAL_OUTPUT_PADDING).abs() < 1.5,
            "{below}px under the last line"
        );
        // Another frame builds nothing.
        let before = built();
        redraw(cx);
        assert_eq!(built() - before, 0);
        // New output builds only its own line, though every line moved up
        // one place as the oldest left the scrollback.
        let before = built();
        desktop.update(cx, |desktop, cx| {
            let shell = desktop
                .terminal_panel
                .as_mut()
                .unwrap()
                .selected_mut()
                .unwrap();
            shell.screen.feed(b"line 6001\r\n");
            desktop.terminal_scroll.scroll_to_bottom();
            cx.notify();
        });
        redraw(cx);
        redraw(cx);
        assert!(built() - before <= 3, "built {} rows", built() - before);
        // A drag from one row to the next selects across them, and the
        // window's copy reads the lines joined by a newline.
        let count = desktop.read_with(cx, |desktop, _| desktop.terminal_rows.count);
        let from = cx
            .debug_bounds(Box::leak(
                format!("terminal-row-{}", count - 3).into_boxed_str(),
            ))
            .expect("the line before last is in view");
        let to = cx
            .debug_bounds(Box::leak(
                format!("terminal-row-{}", count - 2).into_boxed_str(),
            ))
            .expect("the last line is in view");
        let start = point(from.left() + px(1.0), from.center().y);
        let end = point(to.left() + px(200.0), to.center().y);
        cx.simulate_mouse_move(start, None, gpui::Modifiers::default());
        cx.simulate_mouse_down(start, MouseButton::Left, gpui::Modifiers::default());
        cx.simulate_mouse_move(end, MouseButton::Left, gpui::Modifiers::default());
        cx.simulate_mouse_up(end, MouseButton::Left, gpui::Modifiers::default());
        redraw(cx);
        cx.dispatch_action(CopyRenderedSelection);
        let copied = cx.update(|_, cx| cx.read_from_clipboard().and_then(|item| item.text()));
        assert_eq!(copied.as_deref(), Some("line 6000\nline 6001"));
        // A selection across lines copies them as drawn, joined by newlines.
        desktop.read_with(cx, |desktop, _| {
            let line = |index: usize| {
                desktop
                    .terminal_panel
                    .as_ref()
                    .unwrap()
                    .selected()
                    .unwrap()
                    .screen
                    .rendered_line_in(index, true, TerminalPalette::Dark)
                    .unwrap()
                    .text
            };
            let stride = selection::LINE_STRIDE;
            let copied = desktop
                .terminal_selection_text("shell", 10 * stride + 2..12 * stride + 4)
                .unwrap();
            assert_eq!(
                copied,
                format!("{}\n{}\n{}", &line(10)[2..], line(11), &line(12)[..4])
            );
        });
    }

    #[gpui::test]
    fn the_terminal_is_recoloured_when_the_theme_changes(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            desktop.settings.theme = ThemePreset::Dark;
            desktop.model.selected_chat = Some("dock-chat".into());
            desktop.show_native_pane(NativePane::Terminal, cx);
            let mut shell =
                XdDesktop::terminal_tab_from_snapshot(&serde_json::json!({"id": "shell"})).unwrap();
            shell.screen.feed(b"\x1b[31mred\x1b[0m");
            let panel = desktop.terminal_panel.as_mut().unwrap();
            panel.loading = false;
            panel.sessions.push(shell);
            panel.selected = Some("shell".into());
        });
        cx.run_until_parked();
        let red = |render: &TerminalRow| render.highlights[0].1.color;
        let row = |desktop: &mut XdDesktop| {
            desktop.sync_terminal_rows();
            desktop.terminal_row(0).unwrap()
        };
        let dark = desktop.update(cx, |desktop, _| row(desktop));
        assert_eq!(red(&dark), Some(rgb(0xe06c75).into()));
        let light = desktop.update(cx, |desktop, _| {
            desktop.settings.theme = ThemePreset::Light;
            row(desktop)
        });
        assert!(!Rc::ptr_eq(&dark, &light), "the same screen, new colours");
        assert_eq!(red(&light), Some(rgb(0xb3202f).into()));
    }

    #[test]
    fn the_terminal_draws_its_text_attributes_and_inverse_video() {
        let mut screen = TerminalScreen::new(60, 3);
        screen.feed(
            b"\x1b[2mdim\x1b[22m \x1b[4munder\x1b[24m \x1b[9mstrike\x1b[29m \x1b[8mpw\x1b[28m \x1b[7msel",
        );
        for theme in ThemePreset::ALL {
            let colors = theme.colors();
            let palette = theme.terminal_palette();
            let row = TerminalRow::new(screen.rendered_line_in(0, true, palette).unwrap());
            let style = |text: &str| {
                let start = row.text.find(text).unwrap();
                row.highlights
                    .iter()
                    .find(|(range, _)| range.start == start)
                    .map(|(_, style)| *style)
                    .unwrap_or_default()
            };
            assert!(style("under").underline.is_some(), "{theme:?}");
            assert!(style("strike").strikethrough.is_some(), "{theme:?}");
            assert!(style("dim").color.is_some(), "{theme:?}");
            assert_ne!(style("dim").color, Some(rgb(colors.text).into()));
            // Hidden text is still in the row, for a selection to copy, and
            // drawn in the ground's colour.
            assert!(row.text.contains("pw"));
            assert_eq!(style("pw").color, Some(rgb(colors.background).into()));
            // Inverse video with no colours set: the theme's text colour
            // behind the ground's.
            assert_eq!(
                style("sel").background_color,
                Some(rgb(colors.text).into()),
                "{theme:?}"
            );
            assert_eq!(style("sel").color, Some(rgb(colors.background).into()));
            // The cursor sits on the selection's last cell, after "sel": it
            // takes the cell's colours the other way round to show there.
            let mut on_selection = TerminalScreen::new(60, 3);
            on_selection.feed(b"\x1b[7msel\x1b[D");
            let row = TerminalRow::new(on_selection.rendered_line_in(0, true, palette).unwrap());
            assert_eq!(row.cursor, Some(2..3));
            assert_eq!(
                row.cursor_colors,
                Some((colors.background, colors.text)),
                "{theme:?}"
            );
        }
        // The plain cursor keeps the theme's colours.
        let mut plain = TerminalScreen::new(60, 3);
        plain.feed(b"$ ");
        let row = TerminalRow::new(
            plain
                .rendered_line_in(0, true, TerminalPalette::Dark)
                .unwrap(),
        );
        assert_eq!(row.cursor_colors, None);
    }

    #[cfg(unix)]
    #[gpui::test]
    fn a_theme_change_tells_each_terminal_its_new_colours(cx: &mut gpui::TestAppContext) {
        use std::io::BufRead;
        let (host, mut requests) = socket_host("terminal-colours-test");
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            desktop.host = Some(host.clone());
            desktop.model.selected_chat = Some("dock-chat".into());
            desktop.show_native_pane(NativePane::Terminal, cx);
            let panel = desktop.terminal_panel.as_mut().unwrap();
            for id in ["shell", "build"] {
                panel.sessions.push(
                    XdDesktop::terminal_tab_from_snapshot(&serde_json::json!({"id": id})).unwrap(),
                );
            }
            desktop.settings.theme = ThemePreset::Light;
            desktop.send_terminal_colors();
        });
        let light = ThemePreset::Light.colors();
        let mut told = Vec::new();
        while told.len() < 2 {
            let mut line = String::new();
            requests.read_line(&mut line).expect("a colours request");
            let request: Value = serde_json::from_str(&line).unwrap();
            if request["op"] == "terminal-colors" {
                assert_eq!(request["foreground"], light.text);
                assert_eq!(request["background"], light.background);
                told.push(request["terminal"].as_str().unwrap().to_owned());
            }
        }
        assert_eq!(told, ["shell", "build"]);

        // A host from before the operation refuses it; that is not an error
        // worth showing.
        desktop.update(cx, |desktop, cx| {
            let refused = serde_json::json!({"ok": false, "error": "not implemented"});
            desktop.handle_reply(
                RequestKind::TerminalColors,
                refused.as_object().unwrap().clone(),
                None,
                cx,
            );
            assert_eq!(desktop.model.connection_error, None);
            assert_eq!(desktop.terminal_panel.as_ref().unwrap().error, None);
        });
    }

