    #[test]
    fn session_signals_put_waiting_ahead_of_work() {
        assert_eq!(
            SessionSignal::of(true, true, true, 2),
            SessionSignal::Waiting
        );
        assert_eq!(
            SessionSignal::of(true, false, true, 2),
            SessionSignal::Working
        );
        assert_eq!(
            SessionSignal::of(false, false, true, 2),
            SessionSignal::Background(2)
        );
        assert_eq!(
            SessionSignal::of(false, false, true, 0),
            SessionSignal::Done
        );
        assert_eq!(
            SessionSignal::of(false, false, false, 0),
            SessionSignal::Idle
        );
        let colors = ThemePreset::Dark.colors();
        assert!(signal_tab(SessionSignal::Idle, colors).is_none());
        assert!(signal_tab(SessionSignal::Background(1), colors).is_some());
        assert_eq!(SessionSignal::Waiting.color(colors), colors.waiting);
        assert_eq!(SessionSignal::Background(1).color(colors), colors.muted);
    }

    #[test]
    fn a_paused_session_says_so_until_it_needs_more() {
        assert_eq!(
            SessionSignal::of(false, false, true, 0).or_paused(true),
            SessionSignal::Paused
        );
        assert_eq!(
            SessionSignal::of(false, false, false, 0).or_paused(true),
            SessionSignal::Paused
        );
        assert_eq!(
            SessionSignal::of(true, false, false, 0).or_paused(true),
            SessionSignal::Working
        );
        assert_eq!(
            SessionSignal::of(false, true, false, 0).or_paused(true),
            SessionSignal::Waiting
        );
        assert_eq!(
            SessionSignal::of(false, false, false, 0).or_paused(false),
            SessionSignal::Idle
        );
        assert_eq!(SessionSignal::Paused.label().to_string(), "Paused");
        assert!(signal_tab(SessionSignal::Paused, ThemePreset::Dark.colors()).is_some());
    }

