    #[gpui::test]
    fn browser_panes_preserve_each_chats_tabs_toggle_and_settings_visibility(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.active_endpoint = ChatEndpoint::Local;
            desktop.model.folders = vec![
                Folder {
                    id: "a".into(),
                    name: "A".into(),
                    parent: None,
                    owner: None,
                    group: false,
                },
                Folder {
                    id: "b".into(),
                    name: "B".into(),
                    parent: None,
                    owner: None,
                    group: false,
                },
            ];
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "a".into(),
                chat_id: "chat-a".into(),
                agent: AgentCli::Codex,
            };
            desktop.settings.browser_sessions.clear();
            desktop.set_browser_open(true);
            let a_key = desktop.browser_scope_key();
            assert_eq!(a_key, "local/chat/chat-a");
            let saved = BrowserSession {
                tabs: vec![
                    Some("http://localhost:3000/preview".into()),
                    Some("https://example.com/docs".into()),
                ],
                active_tab: 1,
            };
            desktop.settings.browser_sessions.insert(
                a_key,
                BrowserState {
                    open: true,
                    session: saved.clone(),
                },
            );
            let a = desktop.sync_browser_pane(window, cx).unwrap();
            assert!(a.read(cx).is_visible());
            assert_eq!(a.read(cx).session(), saved);
            assert_eq!(
                a.read(cx).current_url().as_deref(),
                Some("https://example.com/docs")
            );

            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "a".into(),
                chat_id: "chat-b".into(),
                agent: AgentCli::Codex,
            };
            assert!(!desktop.browser_is_open());
            assert!(desktop.sync_browser_pane(window, cx).is_none());
            assert!(!a.read(cx).is_visible());
            desktop.toggle_browser(cx);
            let b = desktop.sync_browser_pane(window, cx).unwrap();
            assert_ne!(a.entity_id(), b.entity_id());
            assert!(!a.read(cx).is_visible());
            assert!(b.read(cx).is_visible());
            assert_eq!(b.read(cx).current_url(), None);
            desktop.close_browser(cx);
            assert!(!desktop.browser_is_open());
            assert!(desktop.sync_browser_pane(window, cx).is_none());
            assert!(!b.read(cx).is_visible());

            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "a".into(),
                chat_id: "chat-a".into(),
                agent: AgentCli::Codex,
            };
            assert!(desktop.browser_is_open());
            let restored = desktop.sync_browser_pane(window, cx).unwrap();
            assert_eq!(a.entity_id(), restored.entity_id());
            assert_eq!(restored.read(cx).session(), saved);
            assert!(!b.read(cx).is_visible());

            // A popup covers the page rather than taking the pane away.
            desktop.minimal_theme_open = true;
            desktop.sync_browser_pane(window, cx);
            assert!(a.read(cx).is_visible());
            assert!(a.read(cx).is_covered());
            desktop.minimal_theme_open = false;
            desktop.sync_browser_pane(window, cx);
            assert!(a.read(cx).is_visible());
            assert!(!a.read(cx).is_covered());
            desktop.creating_workspace = true;
            desktop.sync_browser_pane(window, cx);
            assert!(a.read(cx).is_covered());
            desktop.creating_workspace = false;
            desktop.sync_browser_pane(window, cx);
            assert!(!a.read(cx).is_covered());
            desktop.browser_drag = Some((100.0, 460));
            desktop.sync_browser_pane(window, cx);
            assert!(a.read(cx).is_visible());
            desktop.browser_drag = None;
            desktop.catalog_drag = Some((100.0, 256));
            desktop.sync_browser_pane(window, cx);
            assert!(a.read(cx).is_visible());
            desktop.catalog_drag = None;

            desktop.settings.remote_ssh_command = Some("ssh remote.example".into());
            desktop.active_endpoint = ChatEndpoint::Remote;
            assert!(!desktop.browser_is_open());
            assert!(desktop.sync_browser_pane(window, cx).is_none());
            desktop.toggle_browser(cx);
            let remote = desktop.sync_browser_pane(window, cx).unwrap();
            assert_ne!(a.entity_id(), remote.entity_id());
            assert!(!a.read(cx).is_visible());
            assert!(remote.read(cx).is_visible());

            desktop.close_browser(cx);
            assert!(desktop.sync_browser_pane(window, cx).is_none());
            assert!(!remote.read(cx).is_visible());
            desktop.active_endpoint = ChatEndpoint::Local;
            assert!(desktop.browser_is_open());
            assert_eq!(
                desktop.sync_browser_pane(window, cx).unwrap().entity_id(),
                a.entity_id()
            );
            assert_eq!(a.read(cx).session(), saved);
        });
    }

    #[gpui::test]
    fn removed_chats_release_their_browser_tabs_without_affecting_other_connections(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.settings.browser_sessions.clear();
            desktop.active_endpoint = ChatEndpoint::Local;
            desktop.model.chats = vec![ChatSummary {
                id: "kept".into(),
                folder: "project".into(),
                title: None,
                backend: "codex".into(),
                branch: None,
                working: false,
                terminal_working: false,
                background_tasks: 0,
                settled_at: None,
                auto_settle_disabled: false,
                paused: false,
                quota_reached: false,
                pull_requests: Vec::new(),
            }];
            for chat_id in ["kept", "removed"] {
                desktop.minimal_route = MinimalRoute::Cli {
                    project_id: "project".into(),
                    chat_id: chat_id.into(),
                    agent: AgentCli::Codex,
                };
                desktop.set_browser_open(true);
                desktop.sync_browser_pane(window, cx).unwrap();
            }
            desktop.settings.remote_ssh_command = Some("ssh remote.example".into());
            desktop.active_endpoint = ChatEndpoint::Remote;
            desktop.set_browser_open(true);
            let remote_key = desktop.browser_scope_key();
            desktop.sync_browser_pane(window, cx).unwrap();
            desktop.active_endpoint = ChatEndpoint::Local;
            let removed = desktop.browser_panes["local/chat/removed"].clone();

            desktop.prune_browser_panes(ChatEndpoint::Local, cx);

            assert!(!removed.read(cx).is_visible());
            assert!(!desktop.browser_panes.contains_key("local/chat/removed"));
            assert!(
                !desktop
                    .settings
                    .browser_sessions
                    .contains_key("local/chat/removed")
            );
            assert!(desktop.browser_panes.contains_key("local/chat/kept"));
            assert!(
                desktop
                    .settings
                    .browser_sessions
                    .contains_key("local/chat/kept")
            );
            assert!(desktop.browser_panes.contains_key(&remote_key));
            assert!(desktop.settings.browser_sessions.contains_key(&remote_key));
        });
    }

    #[cfg(unix)]
    #[gpui::test]
    fn an_agents_browser_command_opens_its_chats_browser_and_is_answered(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::io::BufRead;

        let (host, mut requests) = socket_host("browser-command-test");
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        let chat = |id: &str| ChatSummary {
            id: id.into(),
            folder: "project".into(),
            title: None,
            backend: "claude".into(),
            branch: None,
            working: false,
            terminal_working: false,
            background_tasks: 0,
            settled_at: None,
            auto_settle_disabled: false,
            paused: false,
            quota_reached: false,
            pull_requests: Vec::new(),
        };
        let command = |request: u64, chat: &str| {
            HostUpdate::Event {
            name: "browser-command".into(),
            body: serde_json::json!({"request": request, "chat": chat, "command": {"action": "snapshot"}})
                .as_object()
                .unwrap()
                .clone(),
            attachments: None,
        }
        };
        desktop.update(cx, |desktop, cx| {
            desktop.settings.browser_sessions.clear();
            desktop.active_endpoint = ChatEndpoint::Local;
            desktop.host = Some(host.clone());
            desktop.model.chats = vec![chat("agent"), chat("watched")];
            desktop.model.selected_chat = Some("watched".into());
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "project".into(),
                chat_id: "watched".into(),
                agent: AgentCli::Claude,
            };
            let generation = desktop.connection_generation;
            desktop.handle_host_update(command(7, "agent"), generation, cx);
        });
        cx.run_until_parked();
        let answer = |requests: &mut std::io::BufReader<std::os::unix::net::UnixStream>| {
            let mut line = String::new();
            requests.read_line(&mut line).unwrap();
            serde_json::from_str::<Value>(&line).unwrap()
        };
        // A test window has no engine, so the page cannot run it; the agent
        // is still answered, with why.
        let reply = answer(&mut requests);
        assert_eq!(reply["op"], "browser-result");
        assert_eq!(reply["request"], 7);
        assert_eq!(reply["error"], "The browser has not started.");
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            // The agent's chat now shows its browser, without it covering the
            // chat on screen.
            let pane = desktop.browser_panes["local/chat/agent"].clone();
            assert!(!pane.read(cx).is_visible());
            assert!(desktop.settings.browser_sessions["local/chat/agent"].open);
            assert!(!desktop.browser_is_open());
            assert!(desktop.sync_browser_pane(window, cx).is_none());

            let generation = desktop.connection_generation;
            desktop.handle_host_update(command(8, "watched"), generation, cx);
        });
        cx.run_until_parked();
        assert_eq!(answer(&mut requests)["request"], 8);
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            assert!(desktop.browser_is_open());
            assert!(
                desktop.browser_panes["local/chat/watched"]
                    .read(cx)
                    .is_visible()
            );
            assert!(
                !desktop.browser_panes["local/chat/agent"]
                    .read(cx)
                    .is_visible()
            );
            // Answered commands are no longer running.
            assert!(desktop.browser_commands.lock().is_empty());

            // A chat the tree has not shown yet could belong to a session,
            // whose pane it would share, so it waits for the tree.
            let generation = desktop.connection_generation;
            desktop.handle_host_update(command(9, "unknown"), generation, cx);
        });
        cx.run_until_parked();
        let refused = answer(&mut requests);
        assert_eq!(refused["request"], 9);
        assert_eq!(
            refused["error"],
            "The xd app has not loaded this chat yet. Try again in a few seconds."
        );
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            assert!(!desktop.browser_panes.contains_key("local/chat/unknown"));

            // The agent's page closing itself, off screen, closes its own
            // chat's pane and leaves the one on screen.
            let agent = desktop.browser_panes["local/chat/agent"].clone();
            agent.update(cx, |_, cx| cx.emit(BrowserEvent::Close));
        });
        cx.run_until_parked();
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            assert!(!desktop.settings.browser_sessions["local/chat/agent"].open);
            assert!(desktop.browser_is_open());
            assert!(
                desktop.browser_panes["local/chat/watched"]
                    .read(cx)
                    .is_visible()
            );
        });
    }

    #[test]
    fn the_host_giving_up_stops_its_running_browser_commands() {
        let running = RunningBrowserCommands::default();
        let first = running.start((ChatEndpoint::Local, 1, 1));
        let second = running.start((ChatEndpoint::Local, 1, 2));
        let remote = running.start((ChatEndpoint::Remote, 1, 1));
        let stopped = |flag: &Arc<std::sync::atomic::AtomicBool>| {
            flag.load(std::sync::atomic::Ordering::Acquire)
        };
        // A `browser-cancel` for one command.
        running.cancel(|command| command == (ChatEndpoint::Local, 1, 1));
        assert!(stopped(&first) && !stopped(&second) && !stopped(&remote));
        // A connection that drops takes its commands with it, and no others.
        running.cancel(|(endpoint, _, _)| endpoint == ChatEndpoint::Local);
        assert!(stopped(&second) && !stopped(&remote));
        assert_eq!(
            running.lock().keys().copied().collect::<Vec<_>>(),
            [(ChatEndpoint::Remote, 1, 1)]
        );
        // A reconnected host may use the same number again; finishing the
        // old command leaves the new one's flag.
        let again = running.start((ChatEndpoint::Remote, 2, 1));
        running.finish((ChatEndpoint::Remote, 1, 1));
        running.cancel(|command| command == (ChatEndpoint::Remote, 2, 1));
        assert!(stopped(&again));
    }

    #[gpui::test]
    fn leaving_a_remote_host_stops_its_browser_commands(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            let remote = desktop.browser_commands.start((
                ChatEndpoint::Remote,
                desktop.remote_generation,
                5,
            ));
            let local = desktop.browser_commands.start((
                ChatEndpoint::Local,
                desktop.connection_generation,
                5,
            ));
            desktop.advance_connection_generation(ChatEndpoint::Remote);
            assert!(remote.load(std::sync::atomic::Ordering::Acquire));
            assert!(!local.load(std::sync::atomic::Ordering::Acquire));
        });
    }

    #[cfg(unix)]
    #[test]
    fn a_browser_command_dropped_unanswered_still_answers_the_agent() {
        use std::io::BufRead;

        let (host, mut requests) = socket_host("browser-answer-test");
        let running = RunningBrowserCommands::default();
        let started = running.start((ChatEndpoint::Local, 1, 3));
        drop(BrowserAnswer {
            host: Some(host.clone()),
            request: 3,
            running: Some((running.clone(), (ChatEndpoint::Local, 1, 3))),
        });
        assert!(running.lock().is_empty());
        assert!(!started.load(std::sync::atomic::Ordering::Acquire));
        BrowserAnswer {
            host: Some(host),
            request: 4,
            running: None,
        }
        .send(Ok(serde_json::json!({"text": "Done."})));
        let mut answers = Vec::new();
        for _ in 0..2 {
            let mut line = String::new();
            requests.read_line(&mut line).unwrap();
            answers.push(serde_json::from_str::<Value>(&line).unwrap());
        }
        assert_eq!(answers[0]["request"], 3);
        assert_eq!(
            answers[0]["error"],
            "The browser closed before the command could run."
        );
        // Sent once, not again as it drops.
        assert_eq!(answers[1]["request"], 4);
        assert_eq!(answers[1]["result"]["text"], "Done.");
        let mut extra = String::new();
        assert!(requests.read_line(&mut extra).is_err() || extra.is_empty());
    }

