    #[gpui::test]
    fn inactive_endpoint_preserves_other_terminal_activity_on_close(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            desktop.inactive_model.chats = vec![ChatSummary {
                id: "remote-chat".into(),
                folder: "workspace".into(),
                title: Some("Remote chat".into()),
                backend: "claude".into(),
                branch: Some("main".into()),
                working: false,
                terminal_working: false,
                background_tasks: 0,
                settled_at: None,
                auto_settle_disabled: false,
                paused: false,
                quota_reached: false,
                pull_requests: Vec::new(),
            }];
            let generation = desktop.remote_generation;
            for (terminal, working, aggregate) in [("claude", true, true), ("shell", false, true)] {
                desktop.handle_remote_update(
                    HostUpdate::Event {
                        name: "terminal-activity".into(),
                        body: serde_json::json!({
                            "chat": "remote-chat",
                            "terminal": terminal,
                            "working": working,
                            "terminal_working": aggregate,
                        })
                        .as_object()
                        .unwrap()
                        .clone(),
                        attachments: None,
                    },
                    generation,
                    cx,
                );
            }
            desktop.handle_remote_update(
                HostUpdate::Event {
                    name: "terminal-closed".into(),
                    body: serde_json::json!({
                        "chat": "remote-chat",
                        "terminal": "shell",
                    })
                    .as_object()
                    .unwrap()
                    .clone(),
                    attachments: None,
                },
                generation,
                cx,
            );

            assert!(desktop.inactive_model.chats[0].terminal_working);
        });
    }

